 89 | /**
 90 |  * Converts a canvas element to a PNG base64 string without data URL prefix.
 91 |  * @param {HTMLCanvasElement} canvas
 92 |  * @returns {string} Base64 encoded PNG data.
 93 |  */
 94 | export function canvasToBase64(canvas) {
 95 |   if (!canvas || typeof canvas.toDataURL !== 'function') {
 96 |     return '';
 97 |   }
 98 |   const dataUrl = canvas.toDataURL('image/png');
 99 |   return dataUrl.replace(/^data:image\/png;base64,/, '');
100 | }

