115 |                     if (actionResponse.action.type === 'task_complete') {
116 |                         await finalizeTask(sessionId, 'completed');
117 |                         return { success: true, steps: stepNumber };
118 |                     }
119 |                     if (actionResponse.action.type === 'task_failed') {
120 |                         await finalizeTask(sessionId, 'failed_by_server');
121 |                         return { success: false, reason: actionResponse.action.reasoning_short, steps: stepNumber };
122 |                     }
123 | 
