 1 | // Minimal validation logic since we don't have Pydantic on the client
 2 | // but we want to ensure the server response is structurally sound before executing.
 3 | 
 4 | export function validateActionResponse(response) {
 5 |     if (!response || typeof response !== 'object') {
 6 |         throw new Error("Invalid response: Not an object");
 7 |     }
 8 | 
 9 |     if (!response.session_id) {
10 |         throw new Error("Invalid response: Missing session_id");
11 |     }
12 | 
13 |     if (typeof response.step_number !== 'number') {
14 |         throw new Error("Invalid response: Invalid step_number");
15 |     }
16 | 
17 |     const action = response.action;
18 |     if (!action || typeof action !== 'object') {
19 |         throw new Error("Invalid response: Missing action object");
20 |     }
21 | 
22 |     const validTypes = ['click', 'type', 'scroll', 'wait', 'ask_user_confirmation', 'task_complete', 'task_failed'];
23 |     if (!validTypes.includes(action.type)) {
24 |         throw new Error(`Invalid response: Unknown action type '${action.type}'`);
25 |     }
26 | 
27 |     if (!['safe', 'risky'].includes(action.risk_tier)) {
28 |         throw new Error(`Invalid response: Unknown risk_tier '${action.risk_tier}'`);
29 |     }
30 | 
31 |     return true;
32 | }

