chunk_d9903f6b7355be51.numbered_code:
  1 | /*
  2 |  * Perceive production build.
  3 |  *
  4 |  * - Compiles TS and bundles the three extension contexts with esbuild.
  5 |  *   Service Worker and Offscreen are ES modules (MV3 `type: module` and
  6 |  *   `<script type="module">`); Content Script is an IIFE.
  7 |  * - Copies manifest.json and the offscreen HTML document into dist/.
  8 |  * - Phase 4: copies the ONNX Runtime Web WASM binaries (from
  9 |  *   @huggingface/transformers' bundled onnxruntime-web) into dist/wasm/, and
 10 |  *   the locally-cached `Xenova/yolos-tiny` weights (see `fetch-models.js`,
 11 |  *   `models-cache/`) into dist/models/ — both declared as
 12 |  *   `web_accessible_resources` in manifest.json. Missing model/wasm assets
 13 |  *   are a WARNING, not a build failure: Phase 1-3 (capture/reactivity) work
 14 |  *   without them, and `npm run fetch-models` populates them on demand.
 15 |  * - Completes in a clean dist/ (stale output removed first).
 16 |  * - Fails loudly (non-zero exit + message) on any build error.
 17 |  *
 18 |  * TEST_HOOKS=1 (via `npm run build:test-hooks`) additionally exposes the
 19 |  * `__perceiveTest` / `__perceiveOffscreen` / `__perceive*` hooks used by
 20 |  * verify.js. The default `npm run build` output contains NO test hooks.
 21 |  * Model/wasm assets are bundled identically in both build modes (they are
 22 |  * local files either way, never fetched at runtime — see `vision-runtime.ts`).
 23 |  */
 24 | 
 25 | "use strict";
 26 | 
 27 | const esbuild = require("esbuild");
 28 | const fs = require("fs");
 29 | const path = require("path");
 30 | 
 31 | const root = path.join(__dirname, ".");
 32 | const srcDir = path.join(root, "src");
 33 | const distDir = path.join(root, "dist");
 34 | 
 35 | const TEST_HOOKS = process.env.TEST_HOOKS === "1";
 36 | 
 37 | function fail(message, cause) {
 38 |   console.error(`[build] FAILED: ${message}`);
 39 |   if (cause) console.error((cause && cause.stack) || cause);
 40 |   process.exit(1);
 41 | }
 42 | 
 43 | async function main() {
 44 |   fs.rmSync(distDir, { recursive: true, force: true });
 45 |   fs.mkdirSync(distDir, { recursive: true });
 46 |   fs.mkdirSync(path.join(distDir, "background"), { recursive: true });
 47 |   fs.mkdirSync(path.join(distDir, "content"), { recursive: true });
 48 |   fs.mkdirSync(path.join(distDir, "offscreen"), { recursive: true });
 49 | 
 50 |   const base = {
 51 |     bundle: true,
 52 |     sourcemap: false,
 53 |     minify: false,
 54 |     target: "chrome116",
 55 |     logLevel: "info",
 56 |     define: {
 57 |       "process.env.TEST_HOOKS": JSON.stringify(TEST_HOOKS ? "1" : "0"),
 58 |     },
 59 |   };
 60 | 
 61 |   const entries = [
 62 |     {
 63 |       entry: path.join(srcDir, "background", "service-worker.ts"),
 64 |       out: path.join(distDir, "background", "service-worker.js"),
 65 |       format: "esm",
 66 |     },
 67 |     {
 68 |       entry: path.join(srcDir, "content", "content-script.ts"),
 69 |       out: path.join(distDir, "content", "content-script.js"),
 70 |       format: "iife",
 71 |     },
 72 |     {
 73 |       entry: path.join(srcDir, "offscreen", "offscreen.ts"),
 74 |       out: path.join(distDir, "offscreen", "offscreen.js"),
 75 |       format: "esm",
 76 |     },
 77 |   ];
 78 | 
 79 |   try {
 80 |     await Promise.all(
 81 |       entries.map((e) =>
 82 |         esbuild.build({ ...base, entryPoints: [e.entry], outfile: e.out, format: e.format })
 83 |       )
 84 |     );
 85 |   } catch (cause) {
 86 |     fail("esbuild bundle step", cause);
 87 |   }
 88 | 
 89 |   try {
 90 |     fs.copyFileSync(path.join(srcDir, "manifest.json"), path.join(distDir, "manifest.json"));
 91 |     fs.copyFileSync(
 92 |       path.join(srcDir, "offscreen", "offscreen.html"),
 93 |       path.join(distDir, "offscreen", "offscreen.html")
 94 |     );
 95 |   } catch (cause) {
 96 |     fail("asset copy step", cause);
 97 |   }
 98 | 
 99 |   copyWasmAssets();
100 |   copyModelAssets();
101 | 
102 |   const lantern = Buffer.from(
103 |     fs.readFileSync(path.join(distDir, "manifest.json")).toString()
104 |   ).length;
105 |   console.log(`[build] complete -> ${path.join(distDir)} (manifest ${lantern} bytes)`);
106 |   console.log(`[build] test hooks: ${TEST_HOOKS ? "ENABLED" : "disabled"}`);
107 | }
108 | 
109 | /** Copy ONNX Runtime Web's WASM binaries + glue (bundled inside the
110 |  * @huggingface/transformers dependency) into dist/wasm/. Warns (does not
111 |  * fail the build) if the dependency isn't installed yet — Phases 1-3 don't
112 |  * need it. */
113 | function copyWasmAssets() {
114 |   // npm may hoist onnxruntime-web to the top level (no version conflict) or
115 |   // nest it under @huggingface/transformers/node_modules (version pinned);
116 |   // check both layouts.
117 |   const candidates = [
118 |     path.join(root, "node_modules", "onnxruntime-web", "dist"),
119 |     path.join(
120 |       root,
121 |       "node_modules",
122 |       "@huggingface",
123 |       "transformers",
124 |       "node_modules",
125 |       "onnxruntime-web",
126 |       "dist"
127 |     ),
128 |   ];
129 |   const wasmSrc = candidates.find((p) => fs.existsSync(p));
130 |   if (!wasmSrc) {
131 |     console.warn(
132 |       "[build] WARNING: onnxruntime-web wasm assets not found (run `npm install`); dist/wasm/ will be empty. Phase 4 inference will not work until this is fixed."
133 |     );
134 |     return;
135 |   }
136 |   const wasmOut = path.join(distDir, "wasm");
137 |   fs.mkdirSync(wasmOut, { recursive: true });
138 |   const files = fs
139 |     .readdirSync(wasmSrc)
140 |     .filter((f) => f.startsWith("ort-wasm") || f === "ort.wasm.mjs" || f === "ort.wasm.js");
141 |   files.forEach((f) => fs.copyFileSync(path.join(wasmSrc, f), path.join(wasmOut, f)));
142 |   console.log(`[build] copied ${files.length} wasm asset(s) -> dist/wasm/`);
143 | }
144 | 
145 | /** Copy the locally-cached Xenova/yolos-tiny weights (populated by
146 |  * `npm run fetch-models`) into dist/models/. Warns (does not fail the
147 |  * build) if the cache is empty. */
148 | function copyModelAssets() {
149 |   const modelsSrc = path.join(root, "models-cache");
150 |   if (!fs.existsSync(modelsSrc)) {
151 |     console.warn(
152 |       "[build] WARNING: models-cache/ not found (run `npm run fetch-models`); dist/models/ will be empty. Phase 4 inference will not work until this is fixed."
153 |     );
154 |     return;
155 |   }
156 |   const modelsOut = path.join(distDir, "models");
157 |   let fileCount = 0;
158 |   const copyRecursive = (srcPath, outPath) => {
159 |     fs.mkdirSync(outPath, { recursive: true });
160 |     for (const entry of fs.readdirSync(srcPath, { withFileTypes: true })) {
161 |       const s = path.join(srcPath, entry.name);
162 |       const o = path.join(outPath, entry.name);
163 |       if (entry.isDirectory()) copyRecursive(s, o);
164 |       else {
165 |         fs.copyFileSync(s, o);
166 |         fileCount++;
167 |       }
168 |     }
169 |   };
170 |   copyRecursive(modelsSrc, modelsOut);
171 |   if (fileCount === 0) {
172 |     console.warn(
173 |       "[build] WARNING: models-cache/ is empty (run `npm run fetch-models`); dist/models/ will be empty."
174 |     );
175 |   } else {
176 |     console.log(`[build] copied ${fileCount} model asset file(s) -> dist/models/`);
177 |   }
