chunk_c26214af09e43e60.numbered_code:
 1 | #!/usr/bin/env node
 2 | /*
 3 |  * One-time (or re-run-when-stale) download of the bundled local-vision
 4 |  * model weights (Phase 4). This is the ONLY place in the Dev 1 toolchain
 5 |  * that talks to the network — it populates `models-cache/`, which `build.js`
 6 |  * then copies verbatim into `dist/models/`. The shipped extension itself
 7 |  * (`env.allowRemoteModels = false` in `vision-runtime.ts`) never fetches
 8 |  * anything at runtime.
 9 |  *
10 |  * Files match the `Xenova/yolos-tiny` Optimum ONNX export layout expected by
11 |  * @huggingface/transformers' local-model resolution
12 |  * (`<localModelPath>/<model_id>/<file>`, mirroring its remote path template
13 |  * `{model}/resolve/{revision}/{file}`), and the dtype -> filename suffix
14 |  * mapping baked into the library (`_fp16`, `_quantized` for q8).
15 |  */
16 | "use strict";
17 | 
18 | const https = require("https");
19 | const fs = require("fs");
20 | const path = require("path");
21 | 
22 | const MODEL_ID = "Xenova/yolos-tiny";
23 | const REVISION = "main";
24 | const CACHE_ROOT = path.join(__dirname, "models-cache");
25 | const MODEL_DIR = path.join(CACHE_ROOT, MODEL_ID);
26 | 
27 | const FILES = [
28 |   "config.json",
29 |   "preprocessor_config.json",
30 |   "onnx/model_fp16.onnx",
31 |   "onnx/model_quantized.onnx",
32 | ];
33 | 
34 | function download(url, destPath, redirectsLeft = 5) {
35 |   return new Promise((resolve, reject) => {
36 |     fs.mkdirSync(path.dirname(destPath), { recursive: true });
37 |     const file = fs.createWriteStream(destPath);
38 |     https
39 |       .get(url, { headers: { "User-Agent": "perceive-extension-fetch-models" } }, (res) => {
40 |         if (res.statusCode && res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
41 |           file.close();
42 |           fs.rmSync(destPath, { force: true });
43 |           if (redirectsLeft <= 0) return reject(new Error(`Too many redirects for ${url}`));
44 |           // HF's resolve endpoint issues *relative* redirects; resolve
45 |           // against the current URL's origin (new URL() handles both
46 |           // relative and absolute Location headers correctly).
47 |           const nextUrl = new URL(res.headers.location, url).toString();
48 |           return resolve(download(nextUrl, destPath, redirectsLeft - 1));
49 |         }
50 |         if (res.statusCode !== 200) {
51 |           file.close();
52 |           fs.rmSync(destPath, { force: true });
53 |           return reject(new Error(`GET ${url} -> HTTP ${res.statusCode}`));
54 |         }
55 |         res.pipe(file);
56 |         file.on("finish", () => file.close(() => resolve(undefined)));
57 |       })
58 |       .on("error", (err) => {
59 |         file.close();
60 |         fs.rmSync(destPath, { force: true });
61 |         reject(err);
62 |       });
63 |   });
64 | }
65 | 
66 | async function main() {
67 |   console.log(`[fetch-models] target: ${MODEL_ID}@${REVISION} -> ${MODEL_DIR}`);
68 |   fs.mkdirSync(MODEL_DIR, { recursive: true });
69 | 
70 |   for (const file of FILES) {
71 |     const destPath = path.join(MODEL_DIR, file);
72 |     if (fs.existsSync(destPath) && fs.statSync(destPath).size > 0) {
73 |       console.log(`[fetch-models] cached, skipping: ${file}`);
74 |       continue;
75 |     }
76 |     const url = `https://huggingface.co/${MODEL_ID}/resolve/${REVISION}/${file}`;
77 |     console.log(`[fetch-models] downloading: ${file}`);
78 |     await download(url, destPath);
79 |     const size = fs.statSync(destPath).size;
80 |     console.log(`[fetch-models] done: ${file} (${(size / 1024).toFixed(1)} KB)`);
81 |   }
82 | 
83 |   console.log("[fetch-models] complete. Re-run `npm run build`/`npm run verify` to bundle into dist/.");
84 | }
85 | 
86 | main().catch((err) => {
87 |   console.error("[fetch-models] FAILED:", err.message);
88 |   process.exit(1);
89 | });

