chunk_6da0300d93879b61.numbered_code:
  1 | /**
  2 |  * Capture graph: orchestrates one synchronized DOM + screenshot capture with
  3 |  * timing metadata and LATEST_REQUEST_WINS concurrency (§5.2, §6 of the plan).
  4 |  *
  5 |  * The graph itself is pure and chrome-free (all IO is injected), so unit tests
  6 |  * can drive it with fakes. `service-worker.ts` wires the real chrome impl.
  7 |  */
  8 | 
  9 | import { buildCaptureMetadata, type DomSnapshot } from "../shared/capture";
 10 | import type {
 11 |   CaptureMetadata,
 12 |   CorrelatedCapture,
 13 |   RawVisionResult,
 14 | } from "../shared/types";
 15 | import type { CaptureSource } from "../shared/messages";
 16 | import { MESSAGE_TYPES } from "../shared/messages";
 17 | import {
 18 |   SCREENSHOT_FORMAT,
 19 |   SCREENSHOT_QUALITY,
 20 | } from "../shared/constants";
 21 | 
 22 | export interface ScreenshotOutcome {
 23 |   dataUrl: string;
 24 |   startedAt: number;
 25 |   endedAt: number;
 26 | }
 27 | 
 28 | export interface CaptureGraphDeps {
 29 |   /** Ask the content script for a fresh DOM snapshot. */
 30 |   requestDomCapture(tabId: number, requestId: string, source: CaptureSource): Promise<{
 31 |     domSnapshot: DomSnapshot;
 32 |     domCapturedAt: number;
 33 |   }>;
 34 |   /** Capture the visible tab as a local image (never leaves the process). */
 35 |   captureScreenshot(tabId: number): Promise<ScreenshotOutcome>;
 36 |   /**
 37 |    * Run local vision inference (Phase 4; undefined before then → skipped).
 38 |    * Viewport/dpr are included so the offscreen host can build the plan §8.1
 39 |    * composite cache key (imageHash, viewport, dpr, modelId/version, config).
 40 |    */
 41 |   runAnalysis?(input: {
 42 |     requestId: string;
 43 |     screenshot: ScreenshotOutcome;
 44 |     viewport: { width: number; height: number };
 45 |     devicePixelRatio: number;
 46 |   }): Promise<RawVisionResult>;
 47 |   now(): number;
 48 | }
 49 | 
 50 | export interface CaptureTask {
 51 |   requestId: string;
 52 |   seq: number;
 53 |   tabId: number;
 54 |   source: CaptureSource;
 55 | }
 56 | 
 57 | export interface CorrelatedCapturePackage {
 58 |   capture: CorrelatedCapture;
 59 |   analysis: RawVisionResult | null;
 60 | }
 61 | 
 62 | export type RunCaptureOutcome = CorrelatedCapturePackage;
 63 | 
 64 | /** Execute a single capture: DOM → screenshot → (analysis) with timestamps. */
 65 | export async function runCaptureGraph(
 66 |   deps: CaptureGraphDeps,
 67 |   task: CaptureTask
 68 | ): Promise<RunCaptureOutcome> {
 69 |   const dom = await deps.requestDomCapture(task.tabId, task.requestId, task.source);
 70 |   const screenshot = await deps.captureScreenshot(task.tabId);
 71 | 
 72 |   const domCapturedAt = dom.domCapturedAt;
 73 |   const screenshotStartTime = screenshot.startedAt;
 74 |   const screenshotEndTime = screenshot.endedAt;
 75 | 
 76 |   const timing: CaptureMetadata = buildCaptureMetadata({
 77 |     requestId: task.requestId,
 78 |     domCapturedAt,
 79 |     screenshotCaptureStartedAt: screenshotStartTime,
 80 |     screenshotCapturedAt: screenshotEndTime,
 81 |     viewport: { width: dom.domSnapshot.viewport.width, height: dom.domSnapshot.viewport.height },
 82 |     devicePixelRatio: dom.domSnapshot.devicePixelRatio,
 83 |     scroll: dom.domSnapshot.scroll,
 84 |   });
 85 | 
 86 |   let analysis: RawVisionResult | null = null;
 87 |   if (deps.runAnalysis) {
 88 |     analysis = await deps.runAnalysis({
 89 |       requestId: task.requestId,
 90 |       screenshot,
 91 |       viewport: { width: dom.domSnapshot.viewport.width, height: dom.domSnapshot.viewport.height },
 92 |       devicePixelRatio: dom.domSnapshot.devicePixelRatio,
 93 |     });
 94 |   }
 95 | 
 96 |   const capture: CorrelatedCapture = {
 97 |     requestId: task.requestId,
 98 |     source: task.source,
 99 |     tabId: task.tabId,
100 |     timing,
101 |     domCapturedAt,
102 |     screenshotStartTime,
103 |     screenshotEndTime,
104 |     viewport: { width: dom.domSnapshot.viewport.width, height: dom.domSnapshot.viewport.height },
105 |     devicePixelRatio: dom.domSnapshot.devicePixelRatio,
106 |     scroll: dom.domSnapshot.scroll,
107 |     dom: dom.domSnapshot,
108 |     screenshot: {
109 |       dataUrl: screenshot.dataUrl,
110 |       format: SCREENSHOT_FORMAT,
111 |       quality: SCREENSHOT_QUALITY,
112 |     },
113 |   };
114 | 
115 |   return { capture, analysis };
116 | }
117 | 
118 | export interface OrchestratorState {
119 |   latestSeq: number;
120 |   inflight: CaptureTask | null;
121 |   pending: CaptureTask | null;
122 |   lastResult: RunCaptureOutcome | null;
123 |   superseded: string[];
124 |   capturesCompleted: number;
125 |   /** Most recent genuine failure (DOM/screenshot/analysis threw) — distinct
126 |    * from a request being superseded by a newer one. Diagnostic only. */
127 |   lastError: { requestId: string; message: string } | null;
128 | }
129 | 
130 | export interface CaptureOrchestrator {
131 |   /**
132 |    * Request a capture; LATEST_REQUEST_WINS (serialized, newest supersedes).
133 |    * Resolves with the completed package, or null if the request was
134 |    * superseded by a newer one (plan §6).
135 |    */
136 |   request(params: { requestId: string; tabId: number; source: CaptureSource }): Promise<RunCaptureOutcome | null>;
137 |   /** Drop pending + supersede inflight (navigation / invalidation). */
138 |   invalidate(opts?: { reason?: string }): void;
139 |   getState(): OrchestratorState;
140 | }
141 | 
142 | interface QueuedTask extends CaptureTask {
143 |   resolve: (v: RunCaptureOutcome | null) => void;
144 | }
145 | 
146 | /**
147 |  * LATEST_REQUEST_WINS coordinator (plan §6): at most one capture+inference in
148 |  * flight; a newer request supersedes an older one so its result can never
149 |  * overwrite the newest active result.
150 |  */
151 | export function createCaptureOrchestrator(deps: CaptureGraphDeps): CaptureOrchestrator {
152 |   let latestSeq = 0;
153 |   let inflight: QueuedTask | null = null;
154 |   let pending: QueuedTask | null = null;
155 |   let lastResult: RunCaptureOutcome | null = null;
156 |   const superseded: string[] = [];
157 |   let capturesCompleted = 0;
158 |   let lastError: { requestId: string; message: string } | null = null;
159 | 
160 |   async function pump(task: QueuedTask): Promise<void> {
161 |     try {
162 |       const outcome = await runCaptureGraph(deps, task);
163 |       const isSuperseded = task.seq !== latestSeq;
164 |       if (isSuperseded) {
165 |         superseded.push(task.requestId);
166 |         task.resolve(null);
167 |         return;
168 |       }
169 |       lastResult = outcome;
170 |       capturesCompleted += 1;
171 |       task.resolve(outcome);
172 |     } catch (error) {
173 |       // A genuine failure (DOM/screenshot/analysis threw) is NOT the same
174 |       // as "superseded by a newer request" — record it distinctly so it's
175 |       // diagnosable instead of silently resolving null like a stale request.
176 |       lastError = { requestId: task.requestId, message: String((error as Error)?.message ?? error) };
177 |       task.resolve(null);
178 |     } finally {
179 |       inflight = null;
180 |       const next = pending;
181 |       pending = null;
182 |       if (next) {
183 |         inflight = next;
184 |         void pump(next);
185 |       }
186 |     }
187 |   }
188 | 
189 |   return {
190 |     request(params) {
191 |       latestSeq += 1;
192 |       return new Promise<RunCaptureOutcome | null>((resolve) => {
193 |         const task: QueuedTask = {
194 |           requestId: params.requestId,
195 |           seq: latestSeq,
196 |           tabId: params.tabId,
197 |           source: params.source,
198 |           resolve,
199 |         };
200 |         if (!inflight) {
201 |           inflight = task;
202 |           void pump(task);
203 |         } else {
204 |           // A newer request replaces whatever was pending (LATEST_REQUEST_WINS,
205 |           // plan §6): the task being replaced must still be resolved (never
206 |           // silently dropped) or its caller would hang forever awaiting it.
207 |           if (pending) {
208 |             superseded.push(pending.requestId);
209 |             pending.resolve(null);
210 |           }
211 |           pending = task;
212 |         }
213 |       });
214 |     },
215 |     invalidate(opts) {
216 |       latestSeq += 1;
217 |       const reason = opts?.reason ?? "invalidate";
218 |       if (pending) {
219 |         superseded.push(pending.requestId);
220 |         pending.resolve(null);
221 |         pending = null;
222 |       }
223 |       if (inflight) superseded.push(inflight.requestId);
224 |       void reason;
225 |     },
226 |     getState(): OrchestratorState {
227 |       return { latestSeq, inflight, pending, lastResult, superseded, capturesCompleted, lastError };
228 |     },
229 |   };
230 | }
