232 | /** Message-type helper used by the background wrapper. */
233 | export function captureRequestMessage(requestId: string, tabId: number, source: CaptureSource) {
234 |   return {
235 |     type: MESSAGE_TYPES.DOM_CAPTURE_REQUEST,
236 |     origin: "background" as const,
237 |     requestId,
238 |     timestamp: Date.now(),
239 |     tabId,
240 |     source,
241 |   };
242 | }

