  1 | /**
  2 |  * Service Worker message handler. Pure and testable – no chrome globals here.
  3 |  *
  4 |  * Returns the response Message to send back, or `null` when the message is an
  5 |  * asynchronous event that needs no response.
  6 |  *
  7 |  * Phase 2 routes CAPTURE_REQUEST / MUTATION_DETECTED / INVALIDATE_CACHE into
  8 |  * the (injected) capture orchestrator. DOM_CAPTURE_RESULT and ANALYSIS_RESULT
  9 |  * are never routed here — they are response channels of tabs.sendMessage /
 10 |  * runtime.sendMessage and are consumed directly by the capture graph deps.
 11 |  */
 12 | 
 13 | import {
 14 |   createErrorResponse,
 15 |   MESSAGE_TYPES,
 16 |   parseMessage,
 17 |   type CaptureSource,
 18 |   type Message,
 19 | } from "../shared/messages";
 20 | import type { RunCaptureOutcome } from "./capture-graph";
 21 | import type { ContextType } from "../shared/types";
 22 | 
 23 | export interface SwRuntimeState {
 24 |   startedAt: number;
 25 |   lastPing?: { requestId: string; receivedAt: number; origin: string };
 26 |   lastOffscreenReady?: { requestId: string; documentUrl: string };
 27 |   lastCapture?: { requestId: string; requestReceivedAt: number; source: CaptureSource };
 28 |   lastMutation?: { requestId: string; receivedAt: number; mutationCount: number };
 29 |   cacheEpoch: number;
 30 | }
 31 | 
 32 | export function createSwRuntimeState(): SwRuntimeState {
 33 |   return { startedAt: Date.now(), cacheEpoch: 0 };
 34 | }
 35 | 
 36 | /** Injected capture-graph plumbing (wired to the orchestrator in the SW). */
 37 | export interface SwHandlerDeps {
 38 |   enqueueCapture(input: {
 39 |     requestId: string;
 40 |     tabId: number;
 41 |     source: CaptureSource;
 42 |   }): Promise<RunCaptureOutcome | null>;
 43 |   invalidateCaptures(reason?: string): void;
 44 | }
 45 | 
 46 | /** Context of the sender, resolved by the SW listener (not the pure handler). */
 47 | export interface SwHandlerContext {
 48 |   senderTabId?: number;
 49 | }
 50 | 
 51 | export async function handleSwMessage(
 52 |   input: unknown,
 53 |   state: SwRuntimeState,
 54 |   origin: ContextType = "background",
 55 |   ctx: SwHandlerContext = {},
 56 |   deps?: SwHandlerDeps
 57 | ): Promise<Message | null> {
 58 |   let message: Message;
 59 |   try {
 60 |     message = parseMessage(input);
 61 |   } catch (error) {
 62 |     return createErrorResponse(input, error, origin);
 63 |   }
 64 | 
 65 |   switch (message.type) {
 66 |     case MESSAGE_TYPES.PING: {
 67 |       state.lastPing = {
 68 |         requestId: message.requestId,
 69 |         receivedAt: Date.now(),
 70 |         origin: message.origin,
 71 |       };
 72 |       return {
 73 |         type: MESSAGE_TYPES.PING_RESPONSE,
 74 |         requestId: message.requestId,
 75 |         timestamp: Date.now(),
 76 |         ok: true,
 77 |         origin,
 78 |         swStartedAt: state.startedAt,
 79 |       } satisfies Message;
 80 |     }
 81 |     case MESSAGE_TYPES.OFFSCREEN_READY: {
 82 |       state.lastOffscreenReady = {
 83 |         requestId: message.requestId,
 84 |         documentUrl: message.documentUrl,
 85 |       };
 86 |       return null;
 87 |     }
 88 |     case MESSAGE_TYPES.CAPTURE_REQUEST:
 89 |     case MESSAGE_TYPES.MUTATION_DETECTED: {
 90 |       const source: CaptureSource =
 91 |         message.type === MESSAGE_TYPES.MUTATION_DETECTED
 92 |           ? (message.source ?? "mutation")
 93 |           : (message.source ?? "manual");
 94 |       const tabId = message.type === MESSAGE_TYPES.CAPTURE_REQUEST
 95 |         ? (message.tabId ?? ctx.senderTabId)
 96 |         : (message.tabId ?? ctx.senderTabId);
 97 |       if (!tabId) {
 98 |         return createErrorResponse(
 99 |           message,
100 |           new Error(`${message.type}: no tab available to capture`),
101 |           origin
102 |         );
103 |       }
104 |       if (!deps?.enqueueCapture) {
105 |         return createErrorResponse(
106 |           message,
107 |           new Error(`${message.type}: capture orchestrator not wired`),
108 |           origin
109 |         );
110 |       }
111 |       // getStatus().lastCapture must reflect the most recent capture *event*
112 |       // regardless of its source — it used to be set only for CAPTURE_REQUEST,
113 |       // so a mutation-triggered capture (which completes successfully) never
114 |       // showed up here even though the underlying capture worked correctly.
115 |       state.lastCapture = { requestId: message.requestId, requestReceivedAt: Date.now(), source };
116 |       if (message.type === MESSAGE_TYPES.MUTATION_DETECTED) {
117 |         state.lastMutation = {
118 |           requestId: message.requestId,
119 |           receivedAt: Date.now(),
120 |           mutationCount: message.mutationCount,
121 |         };
122 |       }
123 |       const outcome = await deps.enqueueCapture({
124 |         requestId: message.requestId,
125 |         tabId,
126 |         source,
127 |       });
128 |       if (!outcome) {
129 |         return {
130 |           type: MESSAGE_TYPES.CAPTURE_RESULT,
131 |           requestId: message.requestId,
132 |           timestamp: Date.now(),
133 |           ok: true,
134 |           origin,
135 |           superseded: true,
136 |         } satisfies Message;
137 |       }
138 |       return {
139 |         type: MESSAGE_TYPES.CAPTURE_RESULT,
140 |         requestId: message.requestId,
141 |         timestamp: Date.now(),
142 |         ok: true,
143 |         origin,
144 |         capture: outcome.capture,
145 |         analysis: outcome.analysis,
146 |       } satisfies Message;
147 |     }
148 |     case MESSAGE_TYPES.INVALIDATE_CACHE: {
149 |       state.cacheEpoch += 1;
150 |       deps?.invalidateCaptures?.(`cacheEpoch=${state.cacheEpoch}`);
151 |       return null;
152 |     }
153 |     default:
154 |       return createErrorResponse(
155 |         message,
156 |         new Error(`SW does not handle message type '${message.type as string}'`),
157 |         origin
158 |       );
159 |   }
160 | }

