241 | // Retry so a cold-start race with the (possibly just-restarted) service
242 | // worker cannot permanently fail the handshake: MV3 workers start lazily on
243 | // first event, and a ping issued at document_idle can arrive before the new
244 | // worker instance finishes registering its listener.
245 | async function pingWithRetry(attempts = 15, delayMs = 750): Promise<string | null> {
246 |   for (let attempt = 0; attempt < attempts; attempt++) {
247 |     const requestId = await pingServiceWorker();
248 |     if (requestId) return requestId;
249 |     await new Promise((resolve) => setTimeout(resolve, delayMs));
250 |   }
251 |   return null;
252 | }

