 96 |  * data: label[for], ancestor <label>, aria-label, placeholder, previous
 97 |  * sibling text — same priority order, same signals, no live DOM needed. */
 98 | function resolveLabelText(node: TreeNode, allNodes: readonly TreeNode[]): string | null {
 99 |   const { el } = node;
100 |   const forId = el.attrs.id ?? el.id;
101 |   const byFor = findLabelFor(forId, allNodes);
102 |   if (byFor) return byFor;
103 | 
104 |   let ancestor = node.parent;
105 |   while (ancestor) {
106 |     if (ancestor.el.tag.toLowerCase() === "label" && ancestor.el.text) return ancestor.el.text;
107 |     ancestor = ancestor.parent;
108 |   }
109 | 
110 |   if (el.aria.label) return el.aria.label;
111 |   if (el.attrs.placeholder) return el.attrs.placeholder;
112 | 
113 |   for (let i = node.indexInSiblings - 1; i >= 0; i--) {
114 |     const sib = node.siblings[i];
115 |     if (sib.text) return sib.text;
116 |   }
117 | 
118 |   return null;
119 | }

