122 |  * order (button exclusion → PASSWORD → CARD_NUMBER → EMAIL → AMOUNT →
123 |  * PHONE → NAME → UNKNOWN), reading Dev 1's already-captured fields instead
124 |  * of live attributes. */
125 | export function classifyFromCapturedElement(
126 |   node: TreeNode,
127 |   allNodes: readonly TreeNode[]
128 | ): ElementClassification {
129 |   const { el } = node;
130 |   const tag = el.tag.toLowerCase();
131 |   const role = el.role;
132 |   const typeAttr = (el.type ?? "").toLowerCase();
133 |   const autocompleteAttr = (el.attrs.autocomplete ?? "").toLowerCase();
134 |   const placeholderAttr = (el.attrs.placeholder ?? "").toLowerCase();
135 | 
136 |   if (tag === "button" || typeAttr === "submit" || typeAttr === "button" || role === "button") {
137 |     return { tag: "button", role: "button", label_text: el.text, is_sensitive: false, sensitivity_type: null };
138 |   }
139 | 
140 |   const label_text = resolveLabelText(node, allNodes);
141 |   const elText = (el.text ?? "").trim();
142 | 
143 |   if (typeAttr === "password") {
144 |     return { tag, role, label_text, is_sensitive: true, sensitivity_type: "PASSWORD" };
145 |   }
146 |   if (autocompleteAttr.includes("cc-number")) {
147 |     return { tag, role, label_text, is_sensitive: true, sensitivity_type: "CARD_NUMBER" };
148 |   }
149 |   if (autocompleteAttr.includes("email") || typeAttr === "email") {
150 |     return { tag, role, label_text, is_sensitive: true, sensitivity_type: "EMAIL" };
151 |   }
152 |   if (
153 |     (label_text && /amount|price|total/i.test(label_text)) ||
154 |     (placeholderAttr && /amount|price|total/i.test(placeholderAttr)) ||
155 |     (elText && /amount|price|total|\$\d/i.test(elText))
156 |   ) {
157 |     return { tag, role, label_text: label_text || elText || null, is_sensitive: true, sensitivity_type: "AMOUNT" };
158 |   }
159 |   if (
160 |     autocompleteAttr.includes("tel") ||
161 |     typeAttr === "tel" ||
162 |     (label_text && /phone|mobile|contact number/i.test(label_text)) ||
163 |     (placeholderAttr && /phone|mobile|contact number/i.test(placeholderAttr))
164 |   ) {
165 |     return { tag, role, label_text, is_sensitive: true, sensitivity_type: "PHONE" };
166 |   }
167 |   if (autocompleteAttr.includes("name") || (label_text && /name/i.test(label_text))) {
168 |     return { tag, role, label_text, is_sensitive: true, sensitivity_type: "NAME" };
169 |   }
170 |   return { tag, role, label_text, is_sensitive: false, sensitivity_type: "UNKNOWN" };
