 51 |  * must not catch-and-send-anyway.
 52 |  */
 53 | export function buildSanitizedClientPayload(params: {
 54 |   dom: DomSnapshot;
 55 |   url: string;
 56 |   tokenVault: TokenVaultLike | null;
 57 |   sessionId: string;
 58 |   taskInstruction: string;
 59 |   stepNumber: number;
 60 |   redactedImageBase64?: string;
 61 | }): ClientPayload {
 62 |   const { dom_summary, detection_confidence_notes } = buildDev2DomSummary(params.dom, params.url, params.tokenVault);
 63 | 
 64 |   const payload: ClientPayload = {
 65 |     session_id: params.sessionId,
 66 |     task_instruction: params.taskInstruction,
 67 |     step_number: params.stepNumber,
 68 |     dom_summary: {
 69 |       url: dom_summary.url,
 70 |       elements: dom_summary.elements.map((el) => ({
 71 |         ...el,
 72 |         // number -> string, explicit (see ClientPayloadElement doc above).
 73 |         sensitivity_tier: String(el.sensitivity_tier) as "1" | "2" | "3",
 74 |       })),
 75 |     },
 76 |     detection_confidence_notes,
 77 |     ...(params.redactedImageBase64 ? { redacted_image_base64: params.redactedImageBase64 } : {}),
 78 |   };
 79 | 
 80 |   // Fail-closed hard gate: Dev 2's own recursive payload walk + PII regex,
 81 |   // unmodified. Throws (does not return a boolean to ignore) on any
 82 |   // violation — see leakage-auditor.js.
 83 |   assertSafeToSend(payload, detectPII);
 84 | 
 85 |   return payload;
 86 | }
 87 | 
 88 | /**
 89 |  * Root-cause fix (redaction/coordinate bug): `dom_summary.elements[].bounding_box`
 90 |  * (built above via `buildDev2DomSummary`) is in CSS-pixel space — the same
 91 |  * space as `getBoundingClientRect()` — because that is what the wire contract
 92 |  * (master doc §4.1) and the backend/LLM expect. It is NOT the space the
 93 |  * screenshot bitmap is in: `chrome.tabs.captureVisibleTab` captures at
 94 |  * *device*-pixel resolution (CSS px × devicePixelRatio — confirmed 2x on a
 95 |  * Retina capture in this project's own test evidence). Drawing a redaction
 96 |  * box straight from the wire `bounding_box` onto that screenshot without this
 97 |  * conversion places every box at roughly half its true position/size —
 98 |  * exactly the "misplaced rectangle" symptom. This function is the ONLY place
 99 |  * that conversion should happen, and only sensitive (tier 1/2) elements
100 |  * become redaction regions — never a vision/YOLO detection box, which has no
101 |  * privacy meaning at all and must never be treated as one.
102 |  */
103 | export function buildScreenshotSensitiveRegions(
104 |   payload: Pick<ClientPayload, "dom_summary">,
105 |   devicePixelRatio: number
106 | ): RedactionRegion[] {
107 |   const regions: RedactionRegion[] = [];
108 |   for (const el of payload.dom_summary.elements) {
109 |     if (!el.is_sensitive || !el.bounding_box) continue;
110 |     const tier = Number(el.sensitivity_tier) as 1 | 2 | 3;
111 |     const screenshotRect = cssRectToScreenshotRect(
112 |       { x: el.bounding_box.x, y: el.bounding_box.y, width: el.bounding_box.w, height: el.bounding_box.h },
113 |       devicePixelRatio
114 |     );
115 |     regions.push({
116 |       bounding_box: {
117 |         x: Math.round(screenshotRect.x),
118 |         y: Math.round(screenshotRect.y),
119 |         w: Math.round(screenshotRect.width),
120 |         h: Math.round(screenshotRect.height),
121 |       },
122 |       sensitivity_tier: tier,
123 |     });
124 |   }
125 |   return regions;
126 | }

