 10 |  * Privacy: every field this panel ever renders comes from
 11 |  * `PipelineEventDetail`, which structurally cannot carry a raw sensitive
 12 |  * value (see dev5-events.ts) — action `value` is never even accepted by
 13 |  * that type. Only `actionType`/`targetElementId`/`riskTier`/counts/reasons
 14 |  * are shown, matching the "EMAIL -> [EMAIL_1], never the real value" rule.
 15 |  *
 16 |  * The panel's own root carries `data-perceive-ui="true"` so Dev 1's capture
 17 |  * walker (shared/capture.ts) skips it entirely — it must never become part
 18 |  * of what the LLM sees, and must never affect element_id numbering.
 19 |  */
 20 | 
 21 | import { PIPELINE_EVENT_NAME, type PipelineEventDetail } from "./dev5-events";
 22 | import { PERCEIVE_UI_MARKER_ATTR } from "../shared/constants";
