 76 |   const header = document.createElement("div");
 77 |   header.setAttribute(PERCEIVE_UI_MARKER_ATTR, "true");
 78 |   Object.assign(header.style, {
 79 |     display: "flex",
 80 |     justifyContent: "space-between",
 81 |     alignItems: "center",
