  1 | /**
  2 |  * Real-DOM adapter: converts a live browser `Element` into the structural
  3 |  * `DomElementLike` view used by the shared capture walker. Lives in the
  4 |  * content script side (needs the actual page DOM).
  5 |  */
  6 | 
  7 | import {
  8 |   buildDomSnapshot,
  9 |   type DomSnapshot,
 10 |   type DomElementLike,
 11 |   type RectLike,
 12 | } from "../shared/capture";
 13 | import { captureFromDocumentState, type PageState } from "./page-state";
 14 | import { PERCEIVE_UI_MARKER_ATTR } from "../shared/constants";
 15 | 
 16 | /**
 17 |  * Convert a single real Element to the structural view. `children` traverses
 18 |  * real element children via a lazy adapter.
 19 |  */
 20 | export function toStructural(el: Element): DomElementLike {
 21 |   const $self = el;
 22 |   return {
 23 |     tagName: $self.tagName,
 24 |     getAttribute: (n) => $self.getAttribute(n),
 25 |     getBoundingClientRect: (): RectLike | null => {
 26 |       const r = $self.getBoundingClientRect();
 27 |       return { x: r.x, y: r.y, width: r.width, height: r.height };
 28 |     },
 29 |     textContent: $self.textContent,
 30 |     isContentEditable: ($self as HTMLElement).isContentEditable ?? false,
 31 |     disabled: ($self as HTMLInputElement).disabled ?? false,
 32 |     value: ($self as HTMLInputElement).value ?? null,
 33 |     type: ($self as HTMLInputElement).type ?? undefined,
 34 |     get children() {
 35 |       return Array.from($self.children).map((c) => toStructural(c as HTMLElement));
 36 |     },
 37 |   };
 38 | }
 39 | 
 40 | /**
 41 |  * Dev 3 → Dev 4 integration fix: `actionExecutor.js` targets elements via
 42 |  * `[data-element-id="<id>"]` (falling back to `getElementById`), but
 43 |  * nothing previously set that attribute — Dev 1's `element_id` is a
 44 |  * positional index-path (e.g. "0.1.2.1", from `buildStableId` in
 45 |  * `shared/capture.ts`), generated from serialized data, never written back
 46 |  * onto the real DOM. Every real action would have silently failed to find
 47 |  * its target.
 48 |  *
 49 |  * This walks the SAME root using the SAME traversal order
 50 |  * (`element.children[i]`, depth-first) `serializeElement` uses to assign
 51 |  * `indexPath` — guaranteed to produce identical ids for every element that
 52 |  * ends up in the snapshot (truncation only stops descending further, never
 53 |  * skips/renumbers earlier siblings — confirmed against `serializeElement`).
 54 |  * Call once per capture, right after the DOM walk, before any element_id is
 55 |  * used for targeting.
 56 |  *
 57 |  * IMPORTANT (found via real-Chrome testing): the content script's own
 58 |  * MutationObserver watches `attributes: true`. An earlier version of this
 59 |  * function unconditionally called `setAttribute` on every element on every
 60 |  * capture, which counts as an attribute mutation — creating a feedback loop
 61 |  * (stamp -> mutation observed -> debounced re-capture -> stamp -> ...) that
 62 |  * caused runaway repeated captures and exhausted Chrome's
 63 |  * `captureVisibleTab` per-second quota. Only write when the value actually
 64 |  * differs, so a stable page's second+ capture touches nothing and the loop
 65 |  * breaks after the first pass.
 66 |  */
 67 | export function stampElementIds(root: Element = document.body): void {
 68 |   function setIfChanged(el: Element, id: string): void {
 69 |     if (el.getAttribute("data-element-id") !== id) el.setAttribute("data-element-id", id);
 70 |   }
 71 |   function walk(el: Element, indexPath: number[]): void {
 72 |     setIfChanged(el, indexPath.join("."));
 73 |     for (let i = 0; i < el.children.length; i++) {
 74 |       const child = el.children[i];
 75 |       // Must mirror serializeElement's Dev 5 UI skip exactly, or stamped
 76 |       // ids drift from the ids Dev 2/the backend/the LLM actually see.
 77 |       if (child && child.getAttribute(PERCEIVE_UI_MARKER_ATTR) !== "true") walk(child, [...indexPath, i]);
 78 |     }
 79 |   }
 80 |   // Root itself is index-path [] per buildStableId([]) === "" — matches
 81 |   // serializeElement's very first call (indexPath = [] for the root).
 82 |   setIfChanged(root, "");
 83 |   for (let i = 0; i < root.children.length; i++) {
 84 |     const child = root.children[i];
 85 |     if (child && child.getAttribute(PERCEIVE_UI_MARKER_ATTR) !== "true") walk(child, [i]);
 86 |   }
 87 | }
 88 | 
 89 | /**
 90 |  * Capture the current page DOM as a structural snapshot.
 91 |  * `doc`/`win` injected so the pure build can be tested; defaults to globals.
 92 |  */
 93 | export function captureDomSnapshot(
 94 |   requestId: string,
 95 |   state?: Partial<PageState>
 96 | ): DomSnapshot {
 97 |   const root = (typeof document !== "undefined" ? document.body : null) ?? (typeof document !== "undefined" ? document.documentElement : null);
 98 |   if (!root) {
 99 |     throw new Error("captureDomSnapshot: no document root available");
100 |   }
101 |   const page = captureFromDocumentState(state);
102 |   return buildDomSnapshot(toStructural(root), {
103 |     requestId,
104 |     domCapturedAt: page.domCapturedAt,
105 |     viewport: page.viewport,
106 |     devicePixelRatio: page.devicePixelRatio,
107 |     scroll: page.scroll,
108 |   });
109 | }

chunk_4046fa18505c263d.numbered_code:
 1 | /**
 2 |  * Mutation debouncer (Phase 3, plan §5.1): collapses bursts of DOM mutations
 3 |  * into a single trigger after `debounceMs`. Pure and injectable so Jest can
 4 |  * drive time without a real MutationObserver. The content script wires real
 5 |  * observer records into `recordMutations`.
 6 |  */
 7 | 
 8 | export interface Scheduler {
 9 |   setTimeout(cb: () => void, ms: number): unknown;
10 |   clearTimeout(id: unknown): void;
11 | }
12 | 
13 | const defaultScheduler: Scheduler = {
14 |   setTimeout(cb, ms) {
15 |     return setTimeout(cb, ms);
16 |   },
17 |   clearTimeout(id) {
18 |     clearTimeout(id as ReturnType<typeof setTimeout>);
19 |   },
20 | };
21 | 
22 | export interface MutationWatcherOptions {
23 |   debounceMs: number;
24 |   /** Fired once per debounce window with the total record count inside it. */
25 |   onDebounced: (mutationCount: number) => void;
26 |   scheduler?: Scheduler;
27 | }
28 | 
29 | export class MutationWatcher {
30 |   private pending = 0;
31 |   private timerActive = false;
32 |   private scheduled: unknown = null;
33 |   private readonly scheduler: Scheduler;
34 | 
35 |   constructor(private readonly options: MutationWatcherOptions) {
36 |     this.scheduler = options.scheduler ?? defaultScheduler;
37 |   }
38 | 
39 |   /** Merge `count` new records into the current debounce window. */
40 |   recordMutations(count: number): void {
41 |     if (count <= 0) return;
42 |     this.pending += count;
43 |     if (!this.timerActive) {
44 |       this.timerActive = true;
45 |       this.scheduled = this.scheduler.setTimeout(() => this.fire(), this.options.debounceMs);
46 |     }
47 |   }
48 | 
49 |   /** Immediately emit whatever is pending and cancel the timer. */
50 |   flush(): void {
51 |     if (this.timerActive) {
52 |       this.scheduler.clearTimeout(this.scheduled);
53 |       this.fire();
54 |     }
55 |   }
56 | 
57 |   /** Cancel pending work and drop accumulated counts. */
58 |   disconnect(): void {
59 |     if (this.timerActive) {
60 |       this.scheduler.clearTimeout(this.scheduled);
61 |     }
62 |     this.timerActive = false;
63 |     this.scheduled = null;
64 |     this.pending = 0;
65 |   }
66 | 
67 |   private fire(): void {
68 |     this.timerActive = false;
69 |     this.scheduled = null;
70 |     const count = this.pending;
71 |     this.pending = 0;
72 |     if (count > 0) this.options.onDebounced(count);
73 |   }
74 | }

