 75 | async function realCaptureCurrentState(): Promise<{ dom: DomSnapshot; url: string }> {
 76 |   // Dev 1's own autonomous mutation-triggered captures (and the
 77 |   // `data-element-id` re-stamping that comes with them) must stay paused for
 78 |   // the caller's ENTIRE step, not just this capture — see
 79 |   // `pauseMutationObserving()`'s doc comment and `runTaskLoop`'s pause/resume
 80 |   // wrapping around the whole capture→send→confirm→execute sequence for why.
 81 |   const MAX_SUPERSEDED_RETRIES = 12;
 82 |   for (let attempt = 0; attempt < MAX_SUPERSEDED_RETRIES; attempt++) {
 83 |     const meta = createRequestMeta();
 84 |     const response = (await chrome.runtime.sendMessage({
 85 |       type: MESSAGE_TYPES.CAPTURE_REQUEST,
 86 |       origin: "content-script",
 87 |       source: "manual",
 88 |       ...meta,
 89 |     })) as { ok?: boolean; capture?: { dom: unknown }; error?: string; superseded?: boolean } | undefined;
 90 | 
 91 |     if (response?.ok && response.capture) {
 92 |       return { dom: response.capture.dom as DomSnapshot, url: location.href };
 93 |     }
 94 |     if (response?.superseded) {
 95 |       await new Promise((r) => setTimeout(r, 250 + attempt * 150));
 96 |       continue;
 97 |     }
 98 |     throw new Error(`capture failed: ${response?.error ?? "no response"}`);
 99 |   }
100 |   throw new Error(`capture failed: superseded ${MAX_SUPERSEDED_RETRIES}x in a row`);
101 | }

