130 | async function sendToBackend(payload: ClientPayload): Promise<unknown> {
131 |   assertSafeToSend(payload, detectPII);
132 | 
133 |   const controller = new AbortController();
134 |   const startedAt = Date.now();
135 |   const timeoutId = setTimeout(() => controller.abort(), 25000);
136 |   try {
137 |     const response = await fetch(`${BACKEND_URL}/analyze`, {
138 |       method: "POST",
139 |       headers: { "Content-Type": "application/json" },
140 |       body: JSON.stringify(payload),
141 |       signal: controller.signal,
142 |     });
143 |     clearTimeout(timeoutId);
144 |     if (!response.ok) {
145 |       lastBackendFetchAttempts.push({ startedAt, elapsedMs: Date.now() - startedAt, outcome: `status=${response.status}` });
146 |       throw new TransportError(`Server returned ${response.status}`);
147 |     }
148 |     const actionResponse = await response.json();
149 |     lastBackendFetchAttempts.push({
150 |       startedAt,
151 |       elapsedMs: Date.now() - startedAt,
152 |       outcome: `status=${response.status} action=${JSON.stringify({
153 |         type: actionResponse?.action?.type,
154 |         target: actionResponse?.action?.target_element_id,
155 |         risk: actionResponse?.action?.risk_tier,
156 |       })}`,
157 |     });
158 |     validateActionResponse(actionResponse);
159 |     return actionResponse;
160 |   } catch (err) {
161 |     clearTimeout(timeoutId);
162 |     lastBackendFetchAttempts.push({
163 |       startedAt,
164 |       elapsedMs: Date.now() - startedAt,
165 |       outcome: `error name=${(err as Error)?.name} message=${(err as Error)?.message}`,
166 |     });
167 |     if ((err as { name?: string }).name === "AbortError") {
168 |       throw new TransportError("Request timed out");
169 |     }
170 |     throw err;
171 |   }
172 | }

