211 | export async function testConfirmAndExecute(
212 |   action: { type: string; target_element_id: string | null; value: string | null; risk_tier: string; reasoning_short: string },
213 |   tokenMap: Record<string, string> = {}
214 | ): Promise<{ requiresConfirmationResult: boolean; approved: boolean | null; executionResult: unknown }> {
215 |   const needsConfirm = requiresConfirmation(action);
216 |   let approved: boolean | null = null;
