227 | 
228 | /**
229 |  * Dev 4's real task loop — structure, retry policy, exit-path accounting,
230 |  * and terminal-action/confirmation handling are unchanged from
231 |  * `orchestrator.original.js`. Only the three upstream calls (capture,
232 |  * sanitize, send) are now real.
233 |  */
234 | export async function runTaskLoop(taskInstruction: string): Promise<TaskResult> {
235 |   const sessionId = crypto.randomUUID();
236 |   let stepNumber = 0;
237 | 
238 |   const vault = getVaultForSession(sessionId);
239 |   const resolveToken = (token: string) => vault.resolveToken(token);
240 | 
241 |   try {
242 |     while (stepNumber < RETRY_CONFIG.MAX_STEPS) {
243 |       stepNumber++;
244 |       let retriesLeft = RETRY_CONFIG.MAX_RETRIES_PER_STEP;
245 |       let stepSuccess = false;
246 |       let lastExecutionError: string | undefined;
247 |       let lastAction: unknown;
248 | 
249 |       while (retriesLeft > 0 && !stepSuccess) {
250 |         // Root-cause fix (real QuickShop testing): pausing Dev 1's own
251 |         // autonomous MutationObserver only around the capture sub-step left
252 |         // it free to re-fire (and re-stamp `data-element-id`) during the
253 |         // slow part of a step — the backend/LLM round trip and confirmation
254 |         // wait — which could invalidate the very id the LLM just targeted
255 |         // before `executeAction` ever ran, surfacing as a spurious
256 |         // `target_element_not_found`. Pause for the whole step instead.
257 |         pauseMutationObserving();
258 |         try {
259 |           // 1. Real Dev 1 capture.
260 |           emitPipelineEvent({ stage: PIPELINE_STAGES.CAPTURING, sessionId, stepNumber });
261 |           const captureState = await realCaptureCurrentState();
262 | 
263 |           // 2. Real Dev 2 classification + tokenization + fail-closed audit.
264 |           emitPipelineEvent({ stage: PIPELINE_STAGES.SANITIZING, sessionId, stepNumber });
265 |           const payload = await realBuildSanitizedPayload(captureState, sessionId, taskInstruction, stepNumber);
266 |           const sensitiveElementCount = payload.dom_summary.elements.filter((el) => el.is_sensitive).length;
267 |           emitPipelineEvent({ stage: PIPELINE_STAGES.SENSITIVE_DATA_DETECTED, sessionId, stepNumber, sensitiveElementCount });
268 | 
269 |           // 3. Real Dev 3 backend call.
270 |           emitPipelineEvent({ stage: PIPELINE_STAGES.SENDING_SANITIZED_REQUEST, sessionId, stepNumber });
271 |           emitPipelineEvent({ stage: PIPELINE_STAGES.WAITING_FOR_LLM, sessionId, stepNumber });
272 |           const actionResponse = (await sendToBackend(payload)) as {
273 |             action: { type: string; target_element_id: string | null; value: string | null; risk_tier: string; reasoning_short: string };
274 |           };
275 |           emitPipelineEvent({
276 |             stage: PIPELINE_STAGES.ACTION_RECEIVED,
277 |             sessionId,
278 |             stepNumber,
279 |             actionType: actionResponse.action.type,
280 |             targetElementId: actionResponse.action.target_element_id,
281 |             riskTier: actionResponse.action.risk_tier,
282 |           });
283 | 
284 |           // 4. Terminal actions (Dev 4 original logic, unchanged).
285 |           if (actionResponse.action.type === "task_complete") {
286 |             emitPipelineEvent({ stage: PIPELINE_STAGES.COMPLETED, sessionId, stepNumber });
287 |             await finalizeTask(sessionId, "completed");
288 |             return { success: true, steps: stepNumber };
289 |           }
290 |           if (actionResponse.action.type === "task_failed") {
291 |             emitPipelineEvent({ stage: PIPELINE_STAGES.FAILED, sessionId, stepNumber, reason: actionResponse.action.reasoning_short });
292 |             await finalizeTask(sessionId, "failed_by_server");
293 |             return { success: false, reason: actionResponse.action.reasoning_short, steps: stepNumber };
294 |           }
295 | 
296 |           // 5. Risk-tier confirmation (Dev 4 original logic, unchanged —
297 |           // the server's own risk_tier override from Dev 3 is respected
298 |           // here exactly as returned, never re-evaluated/weakened).
299 |           if (requiresConfirmation(actionResponse.action)) {
300 |             emitPipelineEvent({
301 |               stage: PIPELINE_STAGES.CONFIRMATION_REQUIRED,
302 |               sessionId,
303 |               stepNumber,
304 |               actionType: actionResponse.action.type,
305 |               targetElementId: actionResponse.action.target_element_id,
306 |               riskTier: actionResponse.action.risk_tier,
307 |             });
308 |             const approved = await requestConfirmation(actionResponse.action);
309 |             emitPipelineEvent({ stage: PIPELINE_STAGES.CONFIRMATION_REQUIRED, sessionId, stepNumber, approved });
310 |             if (!approved) {
311 |               emitPipelineEvent({ stage: PIPELINE_STAGES.FAILED, sessionId, stepNumber, reason: "denied_by_user" });
312 |               await finalizeTask(sessionId, "denied_by_user");
313 |               return { success: false, reason: "User denied risky action", steps: stepNumber };
314 |             }
315 |           }
316 | 
317 |           // 6. Real execution (Dev 4's real, unmodified actionExecutor).
318 |           emitPipelineEvent({
319 |             stage: PIPELINE_STAGES.EXECUTING,
320 |             sessionId,
321 |             stepNumber,
322 |             actionType: actionResponse.action.type,
323 |             targetElementId: actionResponse.action.target_element_id,
324 |           });
325 |           lastAction = actionResponse.action;
326 |           const result = await executeAction(actionResponse.action, resolveToken);
327 |           lastBackendFetchAttempts.push({
328 |             startedAt: Date.now(),
329 |             elapsedMs: 0,
330 |             outcome: `executeAction type=${actionResponse.action.type} target=${actionResponse.action.target_element_id} result=${JSON.stringify(result)}`,
331 |           });
332 | 
333 |           if (result.success) {
334 |             stepSuccess = true;
335 |             await delay(RETRY_CONFIG.POST_ACTION_DELAY_MS);
336 |           } else {
337 |             lastExecutionError = result.error;
338 |             console.warn(`[Orchestrator] Step ${stepNumber} execution failed:`, result.error);
339 |             retriesLeft--;
340 |           }
341 |         } catch (err) {
342 |           console.error(`[Orchestrator] Error during step ${stepNumber}:`, err);
343 |           retriesLeft--;
344 |           if (retriesLeft === 0) {
345 |             emitPipelineEvent({ stage: PIPELINE_STAGES.FAILED, sessionId, stepNumber, reason: (err as Error).message });
346 |             await finalizeTask(sessionId, "max_retries_exceeded");
347 |             return { success: false, reason: `Step ${stepNumber} failed after max retries: ${(err as Error).message}` };
348 |           }
349 |         } finally {
350 |           resumeMutationObserving();
351 |         }
352 |       }
353 | 
354 |       if (!stepSuccess) {
355 |         emitPipelineEvent({ stage: PIPELINE_STAGES.FAILED, sessionId, stepNumber, reason: "max_retries_exceeded" });
356 |         await finalizeTask(sessionId, "max_retries_exceeded");
357 |         return {
358 |           success: false,
359 |           reason: `Max retries exceeded (last execution error: ${lastExecutionError ?? "none"}; last action: ${JSON.stringify(lastAction)})`,
360 |         };
361 |       }
362 |     }
363 | 
364 |     emitPipelineEvent({ stage: PIPELINE_STAGES.FAILED, sessionId, stepNumber, reason: "max_steps_exceeded" });
365 |     await finalizeTask(sessionId, "max_steps_exceeded");
366 |     return { success: false, reason: "Max steps exceeded" };
367 |   } catch (fatalError) {
368 |     console.error("[Orchestrator] Fatal error:", fatalError);
369 |     emitPipelineEvent({ stage: PIPELINE_STAGES.FAILED, sessionId, stepNumber, reason: String((fatalError as Error)?.message ?? fatalError) });
370 |     await finalizeTask(sessionId, "fatal_error");
371 |     throw fatalError;
372 |   }
373 | }

