  1 | /**
  2 |  * Helper to resolve nearby label text for a given DOM element.
  3 |  * Checks in order: associated <label for=id> or parent <label>, aria-label, placeholder,
  4 |  * and closest preceding sibling text node within the same parent.
  5 |  * @param {HTMLElement} el
  6 |  * @returns {string|null}
  7 |  */
  8 | function getNearbyLabelText(el) {
  9 |   if (!el || typeof el.getAttribute !== 'function') {
 10 |     return null;
 11 |   }
 12 | 
 13 |   if (el.labels && el.labels.length > 0) {
 14 |     for (let i = 0; i < el.labels.length; i++) {
 15 |       const text = (el.labels[i].textContent || '').trim();
 16 |       if (text) return text;
 17 |     }
 18 |   }
 19 | 
 20 |   if (el.id && el.ownerDocument && typeof el.ownerDocument.querySelector === 'function') {
 21 |     try {
 22 |       const escapeId = typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(el.id) : el.id;
 23 |       const labelEl = el.ownerDocument.querySelector(`label[for="${escapeId}"]`);
 24 |       if (labelEl) {
 25 |         const text = (labelEl.textContent || '').trim();
 26 |         if (text) return text;
 27 |       }
 28 |     } catch (e) {
 29 |       // Fallback if querySelector fails
 30 |     }
 31 |   }
 32 | 
 33 |   if (typeof el.closest === 'function') {
 34 |     const parentLabel = el.closest('label');
 35 |     if (parentLabel) {
 36 |       const text = (parentLabel.textContent || '').trim();
 37 |       if (text) return text;
 38 |     }
 39 |   }
 40 | 
 41 |   const ariaLabel = el.getAttribute('aria-label');
 42 |   if (ariaLabel && ariaLabel.trim()) {
 43 |     return ariaLabel.trim();
 44 |   }
 45 | 
 46 |   const placeholder = el.getAttribute('placeholder');
 47 |   if (placeholder && placeholder.trim()) {
 48 |     return placeholder.trim();
 49 |   }
 50 | 
 51 |   let curr = el.previousSibling;
 52 |   while (curr) {
 53 |     const text = (curr.textContent || '').trim();
 54 |     if (text) {
 55 |       return text;
 56 |     }
 57 |     curr = curr.previousSibling;
 58 |   }
 59 | 
 60 |   return null;
 61 | }
 62 | 
 63 | /**
 64 |  * Classifies a DOM element based on form heuristics and sensitivity rules.
 65 |  * Order of evaluation: PASSWORD -> CARD_NUMBER -> EMAIL -> AMOUNT -> PHONE -> NAME -> UNKNOWN
 66 |  * @param {HTMLElement} el
 67 |  * @returns {{ tag: string, role: string|null, label_text: string|null, is_sensitive: boolean, sensitivity_type: "PASSWORD"|"CARD_NUMBER"|"EMAIL"|"PHONE"|"NAME"|"AMOUNT"|"UNKNOWN"|null }}
 68 |  */
 69 | export function classifyElement(el) {
 70 |   if (!el || typeof el.getAttribute !== 'function') {
 71 |     return {
 72 |       tag: '',
 73 |       role: null,
 74 |       label_text: null,
 75 |       is_sensitive: false,
 76 |       sensitivity_type: 'UNKNOWN'
 77 |     };
 78 |   }
 79 | 
 80 |   const tag = el.tagName ? el.tagName.toLowerCase() : '';
 81 |   const role = el.getAttribute('role') || null;
 82 |   const typeAttr = (el.getAttribute('type') || '').toLowerCase();
 83 |   const autocompleteAttr = (el.getAttribute('autocomplete') || '').toLowerCase();
 84 |   const placeholderAttr = (el.getAttribute('placeholder') || '').toLowerCase();
 85 | 
 86 |   // Hard exclusion for buttons
 87 |   if (tag === 'button' || typeAttr === 'submit' || typeAttr === 'button' || role === 'button') {
 88 |     return {
 89 |       tag: 'button',
 90 |       role: 'button',
 91 |       label_text: el.innerText || el.textContent || null,
 92 |       is_sensitive: false,
 93 |       sensitivity_type: null
 94 |     };
 95 |   }
 96 | 
 97 |   const label_text = getNearbyLabelText(el);
 98 |   const elText = (el.innerText || el.textContent || '').trim();
 99 | 
100 |   // 1. Password
101 |   if (typeAttr === 'password') {
102 |     return {
103 |       tag,
104 |       role,
105 |       label_text,
106 |       is_sensitive: true,
107 |       sensitivity_type: 'PASSWORD'
108 |     };
109 |   }
110 | 
111 |   // 2. Card Number
112 |   if (autocompleteAttr.includes('cc-number')) {
113 |     return {
114 |       tag,
115 |       role,
116 |       label_text,
117 |       is_sensitive: true,
118 |       sensitivity_type: 'CARD_NUMBER'
119 |     };
120 |   }
121 | 
122 |   // 3. Email
123 |   if (autocompleteAttr.includes('email') || typeAttr === 'email') {
124 |     return {
125 |       tag,
126 |       role,
127 |       label_text,
128 |       is_sensitive: true,
129 |       sensitivity_type: 'EMAIL'
130 |     };
131 |   }
132 | 
133 |   // 4. Amount (Checked BEFORE Phone to prioritize price/total displays over ambiguous nearby sibling text)
134 |   if (
135 |     (label_text && /amount|price|total/i.test(label_text)) ||
136 |     (placeholderAttr && /amount|price|total/i.test(placeholderAttr)) ||
137 |     (elText && /amount|price|total|\$\d/i.test(elText))
138 |   ) {
139 |     return {
140 |       tag,
141 |       role,
142 |       label_text: label_text || (elText || null),
143 |       is_sensitive: true,
144 |       sensitivity_type: 'AMOUNT'
145 |     };
146 |   }
147 | 
148 |   // 5. Phone
149 |   if (
150 |     autocompleteAttr.includes('tel') ||
151 |     typeAttr === 'tel' ||
152 |     (label_text && /phone|mobile|contact number/i.test(label_text)) ||
153 |     (placeholderAttr && /phone|mobile|contact number/i.test(placeholderAttr))
154 |   ) {
155 |     return {
156 |       tag,
157 |       role,
158 |       label_text,
159 |       is_sensitive: true,
160 |       sensitivity_type: 'PHONE'
161 |     };
162 |   }
163 | 
164 |   // 6. Name
165 |   if (autocompleteAttr.includes('name') || (label_text && /name/i.test(label_text))) {
166 |     return {
167 |       tag,
168 |       role,
169 |       label_text,
170 |       is_sensitive: true,
171 |       sensitivity_type: 'NAME'
172 |     };
173 |   }
174 | 
175 |   return {
176 |     tag,
177 |     role,
178 |     label_text,
179 |     is_sensitive: false,
180 |     sensitivity_type: 'UNKNOWN'
181 |   };
182 | }
183 | 
184 | let elementIdCounter = 0;
185 | 
186 | /**
187 |  * Generates a stable selector-like ID for an element.
188 |  * @param {HTMLElement} el
189 |  * @returns {string}
190 |  */
191 | export function getElementId(el) {
192 |   if (!el || typeof el.getAttribute !== 'function') {
193 |     return '';
194 |   }
195 | 
196 |   if (el.id && el.id.trim() !== '') {
197 |     return el.id;
198 |   }
199 | 
200 |   if (typeof el.hasAttribute === 'function' && el.hasAttribute('data-ext-id')) {
201 |     return el.getAttribute('data-ext-id');
202 |   }
203 | 
204 |   const generatedId = `ext-el-${Date.now()}-${++elementIdCounter}`;
205 |   if (typeof el.setAttribute === 'function') {
206 |     el.setAttribute('data-ext-id', generatedId);
207 |   }
208 |   return generatedId;
209 | }

chunk_347a231b61d44593.numbered_code:
  1 | const SEMANTIC_TOKEN_PATTERN = /^\[[A-Z0-9_]+(?:\?|: [^\]]+)?\]$/;
  2 | const SENSITIVE_KEY_PATTERN = /password|pwd|secret|credit_card|cvv|ssn|aadhaar|otp/i;
  3 | 
  4 | /**
  5 |  * Recursively walks an object tree and invokes a callback for every string value found.
  6 |  * @param {*} node - Current node in the object tree.
  7 |  * @param {string} path - Dot-notation path to the current node.
  8 |  * @param {function} callback - Called with (stringValue, path) for each string leaf.
  9 |  * @param {Set} seen - Tracks visited references to avoid circular loops.
 10 |  */
 11 | function walkStrings(node, path, callback, seen) {
 12 |   if (node === null || node === undefined) return;
 13 | 
 14 |   if (seen.has(node)) return;
 15 | 
 16 |   if (typeof node === 'string') {
 17 |     callback(node, path);
 18 |     return;
 19 |   }
 20 | 
 21 |   if (typeof node !== 'object') return;
 22 | 
 23 |   seen.add(node);
 24 | 
 25 |   if (Array.isArray(node)) {
 26 |     for (let i = 0; i < node.length; i++) {
 27 |       walkStrings(node[i], path + '[' + i + ']', callback, seen);
 28 |     }
 29 |     return;
 30 |   }
 31 | 
 32 |   const keys = Object.keys(node);
 33 |   for (const key of keys) {
 34 |     const childPath = path ? path + '.' + key : key;
 35 |     walkStrings(node[key], childPath, callback, seen);
 36 |   }
 37 | }
 38 | 
 39 | /**
 40 |  * Scans an outgoing payload for any raw PII values or sensitive text that leaked through redaction.
 41 |  * @param {object} payload - The full payload object to audit.
 42 |  * @param {function} piiDetectFn - PII detection function with signature (text: string) => Array<{type: string, match: string}>
 43 |  * @returns {{ passed: boolean, violations: Array<{path: string, reason: string, matched_type: string}> }}
 44 |  */
 45 | export function auditPayload(payload, piiDetectFn) {
 46 |   const violations = [];
 47 | 
 48 |   if (!payload || typeof payload !== 'object') {
 49 |     return { passed: true, violations };
 50 |   }
 51 | 
 52 |   if (typeof piiDetectFn !== 'function') {
 53 |     return { passed: true, violations };
 54 |   }
 55 | 
 56 |   const seen = new Set();
 57 | 
 58 |   walkStrings(payload, '', function onString(value, path) {
 59 |     // Skip redacted_image_base64 — it's expected binary/opaque data.
 60 |     // But flag a warning if it looks suspiciously short or malformed.
 61 |     if (path === 'redacted_image_base64') {
 62 |       if (typeof value === 'string' && value.length < 100) {
 63 |         violations.push({
 64 |           path,
 65 |           reason: 'redacted_image_base64 is suspiciously short or malformed',
 66 |           matched_type: 'IMAGE_DATA_WARNING'
 67 |         });
 68 |       }
 69 |       return;
 70 |     }
 71 | 
 72 |     // Skip values that are semantic token placeholders
 73 |     if (SEMANTIC_TOKEN_PATTERN.test(value)) {
 74 |       return;
 75 |     }
 76 | 
 77 |     // 1. Check PII detection regex matches
 78 |     const matches = piiDetectFn(value);
 79 |     if (Array.isArray(matches) && matches.length > 0) {
 80 |       for (const match of matches) {
 81 |         violations.push({
 82 |           path,
 83 |           reason: 'raw PII value found outside semantic token',
 84 |           matched_type: match.type || 'UNKNOWN'
 85 |         });
 86 |       }
 87 |     }
 88 | 
 89 |     // 2. Check for unredacted passwords or secrets in sensitive fields/keys
 90 |     if (SENSITIVE_KEY_PATTERN.test(path) && value && !SEMANTIC_TOKEN_PATTERN.test(value)) {
 91 |       violations.push({
 92 |         path,
 93 |         reason: 'unredacted password or secret string found in sensitive field',
 94 |         matched_type: 'PASSWORD'
 95 |       });
 96 |     }
 97 |   }, seen);
 98 | 
 99 |   return {
100 |     passed: violations.length === 0,
101 |     violations
102 |   };
103 | }
104 | 
105 | /**
106 |  * Hard gate that throws a descriptive Error if the payload contains leaked PII.
107 |  * Intended to be called immediately before any fetch() call in the transport module.
108 |  * @param {object} payload - The full payload object to audit.
109 |  * @param {function} piiDetectFn - PII detection function.
110 |  * @throws {Error} If any PII violations are detected.
111 |  */
112 | export function assertSafeToSend(payload, piiDetectFn) {
113 |   const result = auditPayload(payload, piiDetectFn);
114 | 
115 |   if (!result.passed) {
116 |     const details = result.violations
117 |       .map(function (v) {
118 |         return '  - [' + v.matched_type + '] at "' + v.path + '": ' + v.reason;
119 |       })
120 |       .join('\n');
121 | 
122 |     throw new Error(
123 |       'Payload safety audit failed with ' + result.violations.length +
124 |       ' violation(s). Blocking network request.\n' + details
125 |     );
126 |   }
127 | }
128 | 
129 | /**
130 |  * Higher-order transport wrapper enforcing fail-closed security.
131 |  * Guarantees assertSafeToSend runs on the final payload immediately before transportFn is called.
132 |  * If audit fails, transportFn is ZERO-invoked and an Error is thrown.
133 |  *
134 |  * @param {function} transportFn - Network send function with signature (payload) => Promise<any> | any
135 |  * @param {function} piiDetectFn - PII detection function
136 |  * @returns {function(object): Promise<any> | any} Wrapped transport function
137 |  */
138 | export function createSecureTransport(transportFn, piiDetectFn) {
139 |   if (typeof transportFn !== 'function') {
140 |     throw new Error('createSecureTransport requires a valid transport function.');
141 |   }
142 | 
143 |   return function sendSecurePayload(payload) {
144 |     // Hard gate assertion on the FINAL assembled payload immediately before transport
145 |     assertSafeToSend(payload, piiDetectFn);
146 |     return transportFn(payload);
147 |   };
148 | }

