  1 | import { classifyElement, getElementId } from './dom-heuristics.js';
  2 | import { detectPII } from './pii-patterns.js';
  3 | import { classifySensitivity } from './sensitivity-tiers.js';
  4 | import { redactImage, canvasToBase64 } from './redaction-renderer.js';
  5 | 
  6 | /**
  7 |  * Top-level orchestrator function to process page elements and source canvas/image for redaction.
  8 |  * @param {HTMLElement[]} elements - List of DOM elements to classify and inspect.
  9 |  * @param {HTMLCanvasElement | HTMLImageElement} sourceCanvasOrImage - Canvas or image element to redact.
 10 |  * @param {object} tokenVault - Session-scoped Token Vault instance (REQUIRED).
 11 |  * @returns {{
 12 |  *   dom_summary: {
 13 |  *     url: string,
 14 |  *     elements: Array<{
 15 |  *       element_id: string,
 16 |  *       tag: string,
 17 |  *       role: string | null,
 18 |  *       label_text: string | null,
 19 |  *       is_sensitive: boolean,
 20 |  *       sensitivity_tier: 1 | 2 | 3,
 21 |  *       sensitivity_type: string,
 22 |  *       semantic_token: string | null,
 23 |  *       has_stable_token: boolean,
 24 |  *       bounding_box: {x: number, y: number, w: number, h: number}
 25 |  *     }>
 26 |  *   },
 27 |  *   redacted_image_base64: string,
 28 |  *   detection_confidence_notes: Array<{element_id: string, confidence: number, method: 'dom_heuristic' | 'vision_model' | 'ocr_regex'}>,
 29 |  *   redacted_regions: Array<{element_id: string, bounding_box: {x: number, y: number, w: number, h: number}, sensitivity_tier: 1 | 2 | 3, semantic_token: string | null}>
 30 |  * }}
 31 |  */
 32 | export function processPageForRedaction(elements = [], sourceCanvasOrImage, tokenVault) {
 33 |   const currentUrl = typeof window !== 'undefined' && window.location ? window.location.href : '';
 34 | 
 35 |   const summaryElements = [];
 36 |   const confidenceNotes = [];
 37 |   const sensitiveRegions = [];
 38 |   const sensitiveRawValues = [];
 39 |   const redactedRegionsList = [];
 40 | 
 41 |   if (Array.isArray(elements)) {
 42 |     for (const el of elements) {
 43 |       if (!el) continue;
 44 | 
 45 |       const element_id = getElementId(el);
 46 |       const elementClassification = classifyElement(el);
 47 | 
 48 |       const rect = typeof el.getBoundingClientRect === 'function'
 49 |         ? el.getBoundingClientRect()
 50 |         : { x: 0, y: 0, left: 0, top: 0, width: 0, height: 0 };
 51 | 
 52 |       const bounding_box = {
 53 |         x: Math.round(rect.x || rect.left || 0),
 54 |         y: Math.round(rect.y || rect.top || 0),
 55 |         w: Math.round(rect.width || 0),
 56 |         h: Math.round(rect.height || 0)
 57 |       };
 58 | 
 59 |       // 1. Extract rawValue by priority order
 60 |       let rawValue = null;
 61 |       if (el.value !== undefined && el.value !== null && String(el.value).trim() !== '') {
 62 |         rawValue = el.value;
 63 |       } else if (el.innerText && el.innerText.trim() !== '') {
 64 |         rawValue = el.innerText.trim();
 65 |       } else {
 66 |         rawValue = null;
 67 |       }
 68 | 
 69 |       const textToScan = rawValue || el.textContent || '';
 70 |       const piiMatches = detectPII(textToScan);
 71 | 
 72 |       // 2. Classify sensitivity passing rawValue and tokenVault
 73 |       const sensitivity = classifySensitivity(elementClassification, piiMatches, rawValue, tokenVault);
 74 |       const { sensitivity_tier, sensitivity_type, semantic_token } = sensitivity;
 75 |       const is_sensitive = sensitivity_tier !== 3;
 76 | 
 77 |       // 3. Verify token presence in vault
 78 |       const has_stable_token = Boolean(
 79 |         semantic_token &&
 80 |         tokenVault &&
 81 |         typeof tokenVault.hasToken === 'function' &&
 82 |         tokenVault.hasToken(semantic_token)
 83 |       );
 84 | 
 85 |       summaryElements.push({
 86 |         element_id,
 87 |         tag: elementClassification.tag,
 88 |         role: elementClassification.role,
 89 |         label_text: elementClassification.label_text,
 90 |         is_sensitive,
 91 |         sensitivity_tier,
 92 |         sensitivity_type,
 93 |         semantic_token,
 94 |         has_stable_token,
 95 |         bounding_box
 96 |       });
 97 | 
 98 |       let confidence = 0.92;
 99 |       let method = 'dom_heuristic';
100 | 
101 |       if (elementClassification && elementClassification.sensitivity_type !== 'UNKNOWN') {
102 |         confidence = 0.92;
103 |         method = 'dom_heuristic';
104 |       } else if (piiMatches && piiMatches.length > 0) {
105 |         confidence = 0.6;
106 |         method = 'ocr_regex';
107 |       }
108 | 
109 |       confidenceNotes.push({
110 |         element_id,
111 |         confidence,
112 |         method
113 |       });
114 | 
115 |       if (sensitivity_tier === 1 || sensitivity_tier === 2) {
116 |         sensitiveRegions.push({
117 |           bounding_box,
118 |           sensitivity_tier
119 |         });
120 | 
121 |         redactedRegionsList.push({
122 |           element_id,
123 |           bounding_box,
124 |           sensitivity_tier,
125 |           semantic_token
126 |         });
127 | 
128 |         if (rawValue && String(rawValue).trim()) {
129 |           sensitiveRawValues.push(String(rawValue).trim());
130 |         }
131 |         for (const m of piiMatches) {
132 |           if (m && m.match && m.match.trim()) {
133 |             sensitiveRawValues.push(m.match.trim());
134 |           }
135 |         }
136 |       }
137 |     }
138 |   }
139 | 
140 |   const redactedCanvas = redactImage(sourceCanvasOrImage, sensitiveRegions);
141 |   const redacted_image_base64 = canvasToBase64(redactedCanvas);
142 | 
143 |   const output = {
144 |     dom_summary: {
145 |       url: currentUrl,
146 |       elements: summaryElements
147 |     },
148 |     redacted_image_base64,
149 |     detection_confidence_notes: confidenceNotes,
150 |     redacted_regions: redactedRegionsList
151 |   };
152 | 
153 |   // Top-level Recursive Guard Assertion: confirm no sensitive raw values leak into output object tree
154 |   function walkAndAssert(node, path) {
155 |     if (node === null || node === undefined) return;
156 |     if (path === 'redacted_image_base64') return;
157 | 
158 |     if (typeof node === 'string') {
159 |       for (const rawVal of sensitiveRawValues) {
160 |         if (!rawVal || rawVal.length < 3) continue;
161 |         if (node.includes(rawVal) && !node.startsWith('[')) {
162 |           throw new Error(`Privacy Assertion Violated: Raw sensitive value "${rawVal}" found in output object at "${path}"`);
163 |         }
164 |       }
165 |       return;
166 |     }
167 | 
168 |     if (typeof node !== 'object') return;
169 | 
170 |     if (Array.isArray(node)) {
171 |       for (let i = 0; i < node.length; i++) {
172 |         walkAndAssert(node[i], `${path}[${i}]`);
173 |       }
174 |       return;
175 |     }
176 | 
177 |     for (const key of Object.keys(node)) {
178 |       const childPath = path ? `${path}.${key}` : key;
179 |       walkAndAssert(node[key], childPath);
180 |     }
181 |   }
182 | 
183 |   walkAndAssert(output, '');
184 | 
185 |   return output;
186 | }

