  1 | /** Module-level flag controlling Tier 2 redaction (default: true) */
  2 | export let REDACT_TIER_2 = true;
  3 | 
  4 | /**
  5 |  * Sets the module-level flag for Tier 2 redaction.
  6 |  * @param {boolean} flag
  7 |  */
  8 | export function setRedactTier2(flag) {
  9 |   REDACT_TIER_2 = Boolean(flag);
 10 | }
 11 | 
 12 | /**
 13 |  * Redacts sensitive regions on an image or canvas by drawing solid black standardized boxes.
 14 |  * @param {HTMLCanvasElement | HTMLImageElement} sourceCanvasOrImage
 15 |  * @param {Array<{bounding_box: {x: number, y: number, w: number, h: number}, sensitivity_tier: 1|2|3}>} sensitiveRegions
 16 |  * @returns {HTMLCanvasElement} A new canvas containing the redacted image.
 17 |  */
 18 | export function redactImage(sourceCanvasOrImage, sensitiveRegions = []) {
 19 |   if (!sourceCanvasOrImage) {
 20 |     throw new Error('Source canvas or image is required.');
 21 |   }
 22 | 
 23 |   const width = sourceCanvasOrImage.width || sourceCanvasOrImage.naturalWidth || 0;
 24 |   const height = sourceCanvasOrImage.height || sourceCanvasOrImage.naturalHeight || 0;
 25 | 
 26 |   let outputCanvas;
 27 |   if (typeof document !== 'undefined' && typeof document.createElement === 'function') {
 28 |     outputCanvas = document.createElement('canvas');
 29 |     outputCanvas.width = width;
 30 |     outputCanvas.height = height;
 31 |   } else {
 32 |     // Environment fallback (e.g. Node test runner without DOM)
 33 |     outputCanvas = {
 34 |       width,
 35 |       height,
 36 |       getContext: () => ({
 37 |         drawImage: () => {},
 38 |         fillRect: () => {},
 39 |         clearRect: () => {},
 40 |         getImageData: () => ({ data: new Uint8ClampedArray(4) })
 41 |       }),
 42 |       toDataURL: () => (typeof sourceCanvasOrImage.toDataURL === 'function' ? sourceCanvasOrImage.toDataURL('image/png') : '')
 43 |     };
 44 |   }
 45 | 
 46 |   const ctx = outputCanvas.getContext('2d');
 47 |   if (ctx && typeof ctx.drawImage === 'function') {
 48 |     ctx.drawImage(sourceCanvasOrImage, 0, 0, width, height);
 49 |   }
 50 | 
 51 |   if (Array.isArray(sensitiveRegions)) {
 52 |     for (const region of sensitiveRegions) {
 53 |       if (!region || !region.bounding_box) continue;
 54 | 
 55 |       const tier = region.sensitivity_tier;
 56 |       if (tier === 1 || (tier === 2 && REDACT_TIER_2)) {
 57 |         const { x, y, w, h } = region.bounding_box;
 58 | 
 59 |         let catW = 260;
 60 |         let catH = 24;
 61 | 
 62 |         if (w <= 80 && h <= 24) {
 63 |           catW = 80;
 64 |           catH = 24;
 65 |         } else if (w <= 160 && h <= 24) {
 66 |           catW = 160;
 67 |           catH = 24;
 68 |         } else {
 69 |           catW = 260;
 70 |           catH = 24;
 71 |         }
 72 | 
 73 |         const centerX = x + w / 2;
 74 |         const centerY = y + h / 2;
 75 |         const drawX = centerX - catW / 2;
 76 |         const drawY = centerY - catH / 2;
 77 | 
 78 |         if (ctx && typeof ctx.fillRect === 'function') {
 79 |           ctx.fillStyle = '#000000';
 80 |           ctx.fillRect(drawX, drawY, catW, catH);
 81 |         }
 82 |       }
 83 |     }
 84 |   }
 85 | 
 86 |   return outputCanvas;
 87 | }
 88 | 
 89 | /**
 90 |  * Converts a canvas element to a PNG base64 string without data URL prefix.
 91 |  * @param {HTMLCanvasElement} canvas
 92 |  * @returns {string} Base64 encoded PNG data.
 93 |  */
 94 | export function canvasToBase64(canvas) {
 95 |   if (!canvas || typeof canvas.toDataURL !== 'function') {
 96 |     return '';
 97 |   }
 98 |   const dataUrl = canvas.toDataURL('image/png');
 99 |   return dataUrl.replace(/^data:image\/png;base64,/, '');
100 | }

