20 | /**
21 |  * Formats a numeric value into a rough dollar amount range token string.
22 |  * @param {number} val
23 |  * @returns {string}
24 |  */
25 | function formatAmountRange(val) {
26 |   if (isNaN(val) || val === null) return '[AMOUNT]';
27 |   if (val < 10) return '[AMOUNT: $<10]';
28 |   if (val >= 10 && val <= 50) return '[AMOUNT: $10-50]';
29 |   if (val > 50 && val <= 100) return '[AMOUNT: $50-100]';
30 |   if (val > 100 && val <= 500) return '[AMOUNT: $100-500]';
31 |   if (val > 500 && val <= 1000) return '[AMOUNT: $500-1000]';
32 |   return '[AMOUNT: $1000+]';
33 | }

