 1 | /**
 2 |  * Executes a validated action on the real DOM.
 3 |  * @param {Object} action — validated server response action
 4 |  * @param {Function} resolveToken — Dev 2's vault.resolveToken, bound and passed in
 5 |  * @returns {Promise<Object>} — { success: boolean, error?: string, domChanged?: boolean }
 6 |  */
 7 | export async function executeAction(action, resolveToken) {
 8 |     console.log(`[ActionExecutor] Executing action: ${action.type}`);
 9 | 
10 |     if (action.type === 'task_complete' || action.type === 'task_failed') {
11 |         return { success: true, domChanged: false };
12 |     }
13 | 
14 |     if (action.type === 'wait') {
15 |         const delay = parseInt(action.value, 10) || 1000;
16 |         await new Promise(r => setTimeout(r, delay));
17 |         return { success: true, domChanged: false };
18 |     }
19 | 
20 |     // For click, type, scroll, we need a target element
21 |     let targetElement = null;
22 |     if (action.target_element_id) {
23 |         targetElement = document.querySelector(`[data-element-id="${action.target_element_id}"]`);
24 |         if (!targetElement) {
25 |             targetElement = document.getElementById(action.target_element_id);
26 |         }
27 |     }
28 | 
29 |     if (!targetElement && ['click', 'type', 'scroll'].includes(action.type)) {
30 |         return { success: false, error: 'target_element_not_found' };
31 |     }
32 | 
33 |     // Visibility check
34 |     if (targetElement) {
35 |         const rect = targetElement.getBoundingClientRect();
36 |         const isVisible = (rect.width > 0 && rect.height > 0) &&
37 |                           window.getComputedStyle(targetElement).visibility !== 'hidden';
38 |         if (!isVisible || targetElement.disabled) {
39 |             return { success: false, error: 'element_not_interactable' };
40 |         }
41 |     }
42 | 
43 |     try {
44 |         switch (action.type) {
45 |             case 'click':
46 |                 targetElement.click();
47 |                 return { success: true, domChanged: true };
48 | 
49 |             case 'type':
50 |                 let valueToType = action.value || "";
51 |                 
52 |                 // Check if it looks like a token, e.g. [CARD_NUMBER_1]
53 |                 if (valueToType.startsWith('[') && valueToType.endsWith(']')) {
54 |                     const resolved = resolveToken(valueToType);
55 |                     if (!resolved) {
56 |                         return { success: false, error: 'unresolvable_token' };
57 |                     }
58 |                     valueToType = resolved;
59 |                 }
60 | 
61 |                 // Set value and dispatch synthetic events so SPA frameworks pick it up
62 |                 targetElement.value = valueToType;
63 |                 targetElement.dispatchEvent(new Event('input', { bubbles: true }));
64 |                 targetElement.dispatchEvent(new Event('change', { bubbles: true }));
65 |                 
66 |                 return { success: true, domChanged: true };
67 | 
68 |             case 'scroll':
69 |                 targetElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
70 |                 return { success: true, domChanged: false };
71 | 
72 |             case 'ask_user_confirmation':
73 |                 // Will be handled by the orchestrator calling confirmationUI.js
74 |                 return { success: true, domChanged: false };
75 | 
76 |             default:
77 |                 return { success: false, error: 'unknown_action_type' };
78 |         }
79 |     } catch (error) {
80 |         console.error(`[ActionExecutor] Error executing ${action.type}:`, error);
81 |         return { success: false, error: error.message };
82 |     }
83 | }

