 76 | export async function runTaskLoop(taskInstruction) {
 77 |     const sessionId = crypto.randomUUID();
 78 |     let stepNumber = 0;
 79 |     
 80 |     // Track active vaults for E2E testing
 81 |     if (window.__activeVaults === undefined) window.__activeVaults = 0;
 82 |     window.__activeVaults++;
