 85 |     const vault = mockDev2.getVaultForSession(sessionId);
 86 |     const resolveToken = vault.resolveToken.bind(vault);
 87 | 
 88 |     try {
 89 |         while (stepNumber < RETRY_CONFIG.MAX_STEPS) {
 90 |             stepNumber++;
 91 |             let retriesLeft = RETRY_CONFIG.MAX_RETRIES_PER_STEP;
 92 |             let stepSuccess = false;
 93 | 
 94 |             while (retriesLeft > 0 && !stepSuccess) {
 95 |                 try {
 96 |                     // 1. Capture
 97 |                     const snapshot = await mockDev1.captureCurrentState();
 98 | 
 99 |                     // 2. Redact + build payload
100 |                     const payload = await mockDev2.buildSanitizedPayload(snapshot, sessionId, taskInstruction, stepNumber);
101 | 
102 |                     // 3. Send to backend (mocking transport logic directly here for testability without a real backend)
103 |                     // In real code: const actionResponse = await sendToBackend(payload);
104 |                     let actionResponse = null;
105 |                     
106 |                     // --- MOCK BACKEND RESPONSES FOR E2E ---
107 |                     if (window.__mockBackendResponse) {
108 |                         actionResponse = window.__mockBackendResponse(stepNumber, payload);
109 |                     } else {
110 |                         throw new Error("No mock backend provided for E2E tests");
111 |                     }
112 |                     // --------------------------------------
113 | 
114 |                     // 4. Check for terminal actions
115 |                     if (actionResponse.action.type === 'task_complete') {
116 |                         await finalizeTask(sessionId, 'completed');
117 |                         return { success: true, steps: stepNumber };
118 |                     }
119 |                     if (actionResponse.action.type === 'task_failed') {
120 |                         await finalizeTask(sessionId, 'failed_by_server');
121 |                         return { success: false, reason: actionResponse.action.reasoning_short, steps: stepNumber };
122 |                     }
123 | 
124 |                     // 5. Risk-tier confirmation
125 |                     if (requiresConfirmation(actionResponse.action)) {
126 |                         const approved = await requestConfirmation(actionResponse.action);
127 |                         if (!approved) {
128 |                             await finalizeTask(sessionId, 'denied_by_user');
129 |                             return { success: false, reason: 'User denied risky action', steps: stepNumber };
130 |                         }
131 |                     }
