150 |                     retriesLeft--;
151 |                     if (retriesLeft === 0) {
152 |                         await finalizeTask(sessionId, 'max_retries_exceeded');
153 |                         return { success: false, reason: `Step ${stepNumber} failed after max retries: ${err.message}` };
154 |                     }
155 |                 }
156 |             }
157 |             
158 |             if (!stepSuccess) {
159 |                 // Should be unreachable due to exception throwing inside loop but kept for safety
160 |                 await finalizeTask(sessionId, 'max_retries_exceeded');
161 |                 return { success: false, reason: 'Max retries exceeded' };
