 1 | /**
 2 |  * Dev 2 image redaction, run in the offscreen document (has real
 3 |  * `document`/canvas access, unlike the Service Worker). Uses Dev 2's real
 4 |  * `redactImage`/`canvasToBase64` (`dev2-vendor/redaction-renderer.js`,
 5 |  * unmodified) — this file only decodes the screenshot dataUrl into
 6 |  * something `redactImage` can draw from.
 7 |  *
 8 |  * Runs the SAME real function whether tested in plain Node (its own
 9 |  * built-in `typeof document === 'undefined'` fallback, exercised by
10 |  * `tests/dev2-redaction.test.ts`) or here, in the actual offscreen
11 |  * document — no fork, no reimplementation.
12 |  */
13 | 
14 | import { redactImage, canvasToBase64 } from "../dev2-vendor/redaction-renderer.js";
15 | import type { RedactionRegion, RedactionSamplePoint, RedactionSampleResult } from "../shared/messages";
16 | 
17 | export type SensitiveRegion = RedactionRegion;
18 | 
19 | /**
20 |  * Decode a screenshot dataUrl into an `<img>` element (regular
21 |  * HTMLImageElement, not OffscreenCanvas/ImageBitmap — `redactImage` uses
22 |  * `document.createElement('canvas')` + `ctx.drawImage`, both of which need
23 |  * a real image-like source in this document's live DOM).
24 |  */
25 | function decodeImageElement(dataUrl: string): Promise<HTMLImageElement> {
26 |   return new Promise((resolve, reject) => {
27 |     const img = new Image();
28 |     img.onload = () => resolve(img);
29 |     img.onerror = () => reject(new Error("failed to decode screenshot for redaction"));
30 |     img.src = dataUrl;
31 |   });
32 | }
33 | 
34 | /**
35 |  * Redact `sensitiveRegions` (Dev 2's dom_summary bounding boxes/tiers) onto
36 |  * the captured screenshot and return a PNG data URL. Tier 1 always redacted;
37 |  * Tier 2 redacted unless `redactTier2` is false (mirrors
38 |  * `redaction-renderer.js`'s own `REDACT_TIER_2` flag).
39 |  */
40 | export async function redactScreenshot(
41 |   screenshotDataUrl: string,
42 |   sensitiveRegions: SensitiveRegion[]
43 | ): Promise<string> {
44 |   const img = await decodeImageElement(screenshotDataUrl);
45 |   const canvas = redactImage(img, sensitiveRegions);
46 |   const base64 = canvasToBase64(canvas);
47 |   return `data:image/png;base64,${base64}`;
48 | }
49 | 
50 | function toCanvas(img: HTMLImageElement): HTMLCanvasElement {
51 |   const canvas = document.createElement("canvas");
52 |   canvas.width = img.naturalWidth;
53 |   canvas.height = img.naturalHeight;
54 |   const ctx = canvas.getContext("2d")!;
55 |   ctx.drawImage(img, 0, 0);
56 |   return canvas;
57 | }
58 | 
59 | function samplePixel(canvas: HTMLCanvasElement, x: number, y: number): [number, number, number, number] {
60 |   const ctx = canvas.getContext("2d")!;
61 |   const cx = Math.min(Math.max(Math.round(x), 0), canvas.width - 1);
62 |   const cy = Math.min(Math.max(Math.round(y), 0), canvas.height - 1);
63 |   const data = ctx.getImageData(cx, cy, 1, 1).data;
64 |   return [data[0], data[1], data[2], data[3]];
65 | }
66 | 
67 | /**
68 |  * Redact `sensitiveRegions` onto the screenshot AND, in the same pass,
69 |  * sample pixel colors at `samplePoints` before/after — real, executable
70 |  * proof (not code inspection) that sensitive regions are covered and every
71 |  * other sampled point is left untouched. Runs entirely in this document
72 |  * (the only context with a live canvas), so no image data needs to leave
73 |  * the extension to be verified.
74 |  */
75 | export async function redactScreenshotWithSamples(
76 |   screenshotDataUrl: string,
77 |   sensitiveRegions: SensitiveRegion[],
78 |   samplePoints: RedactionSamplePoint[]
79 | ): Promise<{ redactedDataUrl: string; samples: RedactionSampleResult[] }> {
80 |   const img = await decodeImageElement(screenshotDataUrl);
81 |   const originalCanvas = toCanvas(img);
82 |   const redactedCanvas = redactImage(img, sensitiveRegions) as HTMLCanvasElement;
83 | 
84 |   const samples: RedactionSampleResult[] = samplePoints.map((p) => {
85 |     const before = samplePixel(originalCanvas, p.x, p.y);
86 |     const after = samplePixel(redactedCanvas, p.x, p.y);
87 |     const changed = before.some((v, i) => v !== after[i]);
88 |     const isBlack = after[0] < 30 && after[1] < 30 && after[2] < 30;
89 |     return { label: p.label, isSensitive: p.isSensitive, before, after, changed, isBlack };
90 |   });
91 | 
92 |   const base64 = canvasToBase64(redactedCanvas);
93 |   return { redactedDataUrl: `data:image/png;base64,${base64}`, samples };
94 | }

