  1 | /**
  2 |  * Offscreen Document message handler. Pure and testable – chrome.location
  3 |  * is passed in so this module can be unit-tested.
  4 |  */
  5 | 
  6 | import {
  7 |   createErrorResponse,
  8 |   MESSAGE_TYPES,
  9 |   parseMessage,
 10 |   type Message,
 11 | } from "../shared/messages";
 12 | import type { ContextType } from "../shared/types";
 13 | 
 14 | export interface OffscreenRuntimeState {
 15 |   readyAt: number;
 16 |   documentUrl: string;
 17 | }
 18 | 
 19 | /** Injected so this handler stays testable without the ONNX runtime/DOM. */
 20 | export interface OffscreenHandlerDeps {
 21 |   runAnalysis(input: {
 22 |     requestId: string;
 23 |     screenshotDataUrl: string;
 24 |     viewportWidth: number;
 25 |     viewportHeight: number;
 26 |     devicePixelRatio: number;
 27 |   }): Promise<import("../shared/types").RawVisionResult>;
 28 |   runRedaction?(input: {
 29 |     screenshotDataUrl: string;
 30 |     sensitiveRegions: import("../shared/messages").RedactionRegion[];
 31 |     samplePoints: import("../shared/messages").RedactionSamplePoint[];
 32 |   }): Promise<{
 33 |     redactedDataUrl: string;
 34 |     samples: import("../shared/messages").RedactionSampleResult[];
 35 |   }>;
 36 | }
 37 | 
 38 | export async function handleOffscreenMessage(
 39 |   input: unknown,
 40 |   state: OffscreenRuntimeState,
 41 |   origin: ContextType = "offscreen",
 42 |   deps?: OffscreenHandlerDeps
 43 | ): Promise<Message | null> {
 44 |   let message: Message;
 45 |   try {
 46 |     message = parseMessage(input);
 47 |   } catch (error) {
 48 |     return createErrorResponse(input, error, origin);
 49 |   }
 50 | 
 51 |   switch (message.type) {
 52 |     case MESSAGE_TYPES.OFFSCREEN_PING:
 53 |       return {
 54 |         type: MESSAGE_TYPES.OFFSCREEN_PING_RESPONSE,
 55 |         requestId: message.requestId,
 56 |         timestamp: Date.now(),
 57 |         ok: true,
 58 |         origin,
 59 |         documentUrl: state.documentUrl,
 60 |         readyAt: state.readyAt,
 61 |       } satisfies Message;
 62 |     case MESSAGE_TYPES.ANALYSIS_REQUEST: {
 63 |       if (!deps) {
 64 |         return createErrorResponse(
 65 |           message,
 66 |           new Error("Offscreen ANALYSIS_REQUEST handling is not wired (missing deps)"),
 67 |           origin
 68 |         );
 69 |       }
 70 |       try {
 71 |         const result = await deps.runAnalysis({
 72 |           requestId: message.requestId,
 73 |           screenshotDataUrl: message.screenshot,
 74 |           viewportWidth: message.screenshotContext?.viewportWidth ?? 0,
 75 |           viewportHeight: message.screenshotContext?.viewportHeight ?? 0,
 76 |           devicePixelRatio: message.screenshotContext?.devicePixelRatio ?? 1,
 77 |         });
 78 |         return {
 79 |           type: MESSAGE_TYPES.ANALYSIS_RESULT,
 80 |           requestId: message.requestId,
 81 |           timestamp: Date.now(),
 82 |           ok: true,
 83 |           origin,
 84 |           result,
 85 |         } satisfies Message;
 86 |       } catch (error) {
 87 |         return createErrorResponse(message, error, origin);
 88 |       }
 89 |     }
 90 |     case MESSAGE_TYPES.REDACT_REQUEST: {
 91 |       if (!deps?.runRedaction) {
 92 |         return createErrorResponse(
 93 |           message,
 94 |           new Error("Offscreen REDACT_REQUEST handling is not wired (missing deps)"),
 95 |           origin
 96 |         );
 97 |       }
 98 |       try {
 99 |         const { redactedDataUrl, samples } = await deps.runRedaction({
100 |           screenshotDataUrl: message.screenshot,
101 |           sensitiveRegions: message.sensitiveRegions,
102 |           samplePoints: message.samplePoints ?? [],
103 |         });
104 |         return {
105 |           type: MESSAGE_TYPES.REDACT_RESULT,
106 |           requestId: message.requestId,
107 |           timestamp: Date.now(),
108 |           ok: true,
109 |           origin,
110 |           redactedDataUrl,
111 |           samples,
112 |         } satisfies Message;
113 |       } catch (error) {
114 |         return createErrorResponse(message, error, origin);
115 |       }
116 |     }
117 |     default:
118 |       return createErrorResponse(
119 |         message,
120 |         new Error(`Offscreen does not handle message type '${message.type as string}'`),
121 |         origin
122 |       );
123 |   }
124 | }

chunk_17732f03105ce1a2.numbered_code:
 1 | /**
 2 |  * Offscreen-only image preparation for local vision inference (Phase 4).
 3 |  *
 4 |  * Decodes the captured screenshot dataUrl and, if it exceeds
 5 |  * `SCREENSHOT_MAX_LONG_EDGE` on its longer edge, downscales it to a canvas
 6 |  * before it is handed to the model. This is the one piece of Phase 4 that
 7 |  * genuinely needs DOM/canvas access (`Image`, `OffscreenCanvas`), so unlike
 8 |  * the rest of Dev 1's Phase 4 code it is not unit-testable in plain node;
 9 |  * the pure size math it depends on (`computeDownscaleSize`) lives in
10 |  * `shared/coords.ts` and *is* unit-tested.
11 |  */
12 | 
13 | import { computeDownscaleSize } from "../shared/coords";
14 | import { SCREENSHOT_MAX_LONG_EDGE } from "../shared/constants";
15 | 
16 | export interface PreparedImage {
17 |   /** The (possibly downscaled) image, ready to feed to the model. */
18 |   dataUrl: string;
19 |   /** Natural size of the original screenshot, in screenshot pixels. */
20 |   naturalSize: { width: number; height: number };
21 |   /** Size actually fed to the model (== naturalSize when no downscale occurred). */
22 |   modelSize: { width: number; height: number };
23 | }
24 | 
25 | /** Decode a dataUrl into an ImageBitmap (works in the offscreen document). */
26 | async function decodeImage(dataUrl: string): Promise<ImageBitmap> {
27 |   const response = await fetch(dataUrl);
28 |   const blob = await response.blob();
29 |   return createImageBitmap(blob);
30 | }
31 | 
32 | /**
33 |  * Prepare a captured screenshot for the model: decode it, and downscale via
34 |  * canvas when it exceeds `SCREENSHOT_MAX_LONG_EDGE` on the long edge.
35 |  * Non-JPEG/local-only: the bitmap and canvas never leave this process.
36 |  */
37 | export async function prepareScreenshotForModel(
38 |   screenshotDataUrl: string,
39 |   maxLongEdge: number = SCREENSHOT_MAX_LONG_EDGE
40 | ): Promise<PreparedImage> {
41 |   const bitmap = await decodeImage(screenshotDataUrl);
42 |   const naturalSize = { width: bitmap.width, height: bitmap.height };
43 |   const modelSize = computeDownscaleSize(naturalSize, maxLongEdge);
44 | 
45 |   if (modelSize.width === naturalSize.width && modelSize.height === naturalSize.height) {
46 |     bitmap.close();
47 |     return { dataUrl: screenshotDataUrl, naturalSize, modelSize };
48 |   }
49 | 
50 |   const canvas = new OffscreenCanvas(modelSize.width, modelSize.height);
51 |   const ctx = canvas.getContext("2d");
52 |   if (!ctx) {
53 |     bitmap.close();
54 |     throw new Error("OffscreenCanvas 2d context unavailable");
55 |   }
56 |   ctx.drawImage(bitmap, 0, 0, modelSize.width, modelSize.height);
57 |   bitmap.close();
58 | 
59 |   const outBlob = await canvas.convertToBlob({ type: "image/jpeg", quality: 0.8 });
60 |   const dataUrl = await blobToDataUrl(outBlob);
61 |   return { dataUrl, naturalSize, modelSize };
62 | }
63 | 
64 | function blobToDataUrl(blob: Blob): Promise<string> {
65 |   return new Promise((resolve, reject) => {
66 |     const reader = new FileReader();
67 |     reader.onload = () => resolve(reader.result as string);
68 |     reader.onerror = () => reject(reader.error ?? new Error("FileReader failed"));
69 |     reader.readAsDataURL(blob);
70 |   });
71 | }

