 1 | /**
 2 |  * Perceive Offscreen Document.
 3 |  *
 4 |  * Phase 1: a minimal, idle execution host that:
 5 |  *   - loads successfully
 6 |  *   - announces readiness to the Service Worker (OFFSCREEN_READY)
 7 |  *   - answers OFFSCREEN_PING with OFFSCREEN_PING_RESPONSE
 8 |  *
 9 |  * Phase 4 mounts the real local-vision pipeline here (WebGPU primary, WASM
10 |  * fallback — see `vision-runtime.ts`) and answers ANALYSIS_REQUEST.
11 |  */
12 | 
13 | import { handleOffscreenMessage, type OffscreenRuntimeState } from "./handle-message";
14 | import { runVisionAnalysis } from "./vision-runtime";
15 | import { redactScreenshotWithSamples } from "./dev2-redaction";
16 | import { createRequestMeta } from "../shared/request-id";
17 | import { MESSAGE_TYPES } from "../shared/messages";
18 | import { TEST_HOOKS } from "../shared/constants";
19 | 
20 | const state: OffscreenRuntimeState = {
21 |   readyAt: Date.now(),
22 |   documentUrl: location.href,
23 | };
24 | 
25 | console.info("[Offscreen] ready");
26 | 
27 | /** Types this context must respond to; everything else is ignored so that a
28 |  * broadcast (e.g. content→SW PING or CAPTURE_REQUEST) can never be hijacked
29 |  * by an offscreen ERROR_RESPONSE racing the Service Worker's reply. */
30 | function handledByOffscreen(raw: unknown): raw is { type?: unknown } {
31 |   const type = (raw as { type?: unknown } | null)?.type;
32 |   return (
33 |     type === MESSAGE_TYPES.OFFSCREEN_PING ||
34 |     type === MESSAGE_TYPES.ANALYSIS_REQUEST ||
35 |     type === MESSAGE_TYPES.REDACT_REQUEST
36 |   );
37 | }
38 | 
39 | chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
40 |   if (!handledByOffscreen(message)) return undefined;
41 |   handleOffscreenMessage(message, state, "offscreen", {
42 |     runAnalysis: ({ requestId, screenshotDataUrl, viewportWidth, viewportHeight, devicePixelRatio }) =>
43 |       runVisionAnalysis({ requestId, screenshotDataUrl, viewportWidth, viewportHeight, devicePixelRatio }),
44 |     runRedaction: ({ screenshotDataUrl, sensitiveRegions, samplePoints }) =>
45 |       redactScreenshotWithSamples(screenshotDataUrl, sensitiveRegions, samplePoints),
46 |   })
47 |     .then((response) => {
48 |       if (response) sendResponse(response);
49 |     })
50 |     .catch((error) => {
51 |       console.error("[Offscreen] handler error", error);
52 |     });
53 |   return true;
54 | });
55 | 
56 | // Announce readiness so the Service Worker can track us. No response expected.
57 | chrome.runtime
58 |   .sendMessage({
59 |     type: MESSAGE_TYPES.OFFSCREEN_READY,
60 |     ok: true,
61 |     origin: "offscreen",
62 |     documentUrl: state.documentUrl,
63 |     ...createRequestMeta(),
64 |   })
65 |   .catch(() => {
66 |     /* SW restarts are expected; readiness is best-effort. */
67 |   });
