70 |   globalThis.__perceiveOffscreen = {
71 |     getState: () => ({ readyAt: state.readyAt, documentUrl: state.documentUrl }),
72 |     resourceNames: () => performance.getEntriesByType("resource").map((e) => e.name),
73 |   };
