chunk_7d83c0e1a6fa45d9.numbered_code:
  1 | /**
  2 |  * Offscreen local-vision inference runtime (Phase 4).
  3 |  *
  4 |  * Runs entirely inside the offscreen document (reason `WORKERS`) because
  5 |  * Phase 0 proved `import()` — which transformers.js's ONNX Runtime Web
  6 |  * backend needs for both WASM and WebGPU — is disallowed on
  7 |  * ServiceWorkerGlobalScope (see `spike-results.md`).
  8 |  *
  9 |  * - Backend: WebGPU (`fp16`) primary, WASM (`q8`) fallback, feature-gated on
 10 |  *   `navigator.gpu.requestAdapter()` (plan §7 / handoff §7.3).
 11 |  * - Everything is bundled locally: `env.allowRemoteModels = false`,
 12 |  *   `localModelPath` and the WASM runtime both resolve through
 13 |  *   `chrome.runtime.getURL(...)` — zero network requests at inference time.
 14 |  * - Lazy + idempotent init: the pipeline is created at most once per
 15 |  *   backend, on first use, and reused after (module-level promise cache).
 16 |  * - Results are memoized in the on-device `VisionCacheStore`
 17 |  *   (`shared/vision-cache.ts`), keyed by the plan §8.1 composite key
 18 |  *   (screenshot content hash + viewport + dpr + model id/version/config), so
 19 |  *   an unchanged capture never re-runs the model.
 20 |  */
 21 | 
 22 | import {
 23 |   MODEL_ID,
 24 |   MODEL_DTYPE_CPU,
 25 |   MODEL_DTYPE_GPU,
 26 |   MODEL_VERSION,
 27 |   INFERENCE_THRESHOLD,
 28 |   INFERENCE_CONFIG_HASH,
 29 | } from "../shared/constants";
 30 | import { createVisionCacheStore, lookupVisionCache, storeVisionCache } from "../shared/vision-cache";
 31 | import type { RawVisionResult, VisionDetection } from "../shared/types";
 32 | import { prepareScreenshotForModel } from "./image-prep";
 33 | 
 34 | type Backend = "webgpu" | "wasm";
 35 | 
 36 | /** Minimal shape of a transformers.js object-detection pipeline output item. */
 37 | interface RawDetection {
 38 |   score: number;
 39 |   label: string;
 40 |   box: { xmin: number; ymin: number; xmax: number; ymax: number };
 41 | }
 42 | 
 43 | type Detector = (input: string, options: { threshold: number }) => Promise<RawDetection[]>;
 44 | 
 45 | const cacheStore = createVisionCacheStore(50);
 46 | 
 47 | /** Single in-flight/definitive init promise; re-used across every call. */
 48 | let detectorPromise: Promise<{ detector: Detector; backend: Backend }> | null = null;
 49 | 
 50 | async function detectWebGpuBackend(): Promise<boolean> {
 51 |   const gpu = (globalThis.navigator as Navigator & { gpu?: { requestAdapter(): Promise<unknown> } })
 52 |     .gpu;
 53 |   if (!gpu) return false;
 54 |   try {
 55 |     const adapter = await gpu.requestAdapter();
 56 |     return !!adapter;
 57 |   } catch {
 58 |     return false;
 59 |   }
 60 | }
 61 | 
 62 | async function loadDetector(backend: Backend): Promise<Detector> {
 63 |   // transformers.js is ESM-only; dynamic import works in the offscreen
 64 |   // document (unlike the Service Worker — see Phase 0 spike).
 65 |   const { pipeline, env } = await import("@huggingface/transformers");
 66 | 
 67 |   // SPIKE used env.allowRemoteModels = true to fetch from the HF hub; the
 68 |   // shipped product must never do that (plan: zero network at runtime).
 69 |   // allowLocalModels defaults to false in browser-like environments (which
 70 |   // the offscreen document is), so it must be explicitly enabled or
 71 |   // transformers.js refuses to load from ANY source (verified against a
 72 |   // real build: "Invalid configuration detected: both local and remote
 73 |   // models are disabled").
 74 |   env.allowRemoteModels = false;
 75 |   env.allowLocalModels = true;
 76 |   env.localModelPath = chrome.runtime.getURL("models/");
 77 |   if (env.backends?.onnx?.wasm) {
 78 |     env.backends.onnx.wasm.wasmPaths = chrome.runtime.getURL("wasm/");
 79 |   }
 80 | 
 81 |   const dtype = backend === "webgpu" ? MODEL_DTYPE_GPU : MODEL_DTYPE_CPU;
 82 |   const detector = await pipeline("object-detection", MODEL_ID, {
 83 |     device: backend,
 84 |     dtype,
 85 |   });
 86 |   return detector as unknown as Detector;
 87 | }
 88 | 
 89 | /** Resolve (once) which backend to use and construct its detector. */
 90 | function ensureDetector(): Promise<{ detector: Detector; backend: Backend }> {
 91 |   if (!detectorPromise) {
 92 |     detectorPromise = (async () => {
 93 |       const hasWebGpu = await detectWebGpuBackend();
 94 |       if (hasWebGpu) {
 95 |         try {
 96 |           return { detector: await loadDetector("webgpu"), backend: "webgpu" as const };
 97 |         } catch (error) {
 98 |           console.error("[Offscreen] WebGPU pipeline init failed, falling back to WASM", error);
 99 |         }
100 |       }
101 |       return { detector: await loadDetector("wasm"), backend: "wasm" as const };
102 |     })().catch((error) => {
103 |       // Allow a later call to retry (e.g. transient failure) instead of
104 |       // permanently caching a rejected promise.
105 |       detectorPromise = null;
106 |       throw error;
107 |     });
108 |   }
109 |   return detectorPromise;
110 | }
111 | 
112 | function mapDetections(raw: RawDetection[]): VisionDetection[] {
113 |   return raw.map((d) => ({
114 |     label: d.label,
115 |     confidence: d.score,
116 |     boundingBox: {
117 |       x: d.box.xmin,
118 |       y: d.box.ymin,
119 |       width: Math.max(0, d.box.xmax - d.box.xmin),
120 |       height: Math.max(0, d.box.ymax - d.box.ymin),
121 |     },
122 |   }));
123 | }
124 | 
125 | export interface RunVisionAnalysisInput {
126 |   requestId: string;
127 |   /** Screenshot dataUrl exactly as captured by `chrome.tabs.captureVisibleTab`. */
128 |   screenshotDataUrl: string;
129 |   /** CSS-pixel viewport size + dpr at capture time (plan §8.1 cache key). */
130 |   viewportWidth: number;
131 |   viewportHeight: number;
132 |   devicePixelRatio: number;
133 | }
134 | 
135 | /**
136 |  * Run (or reuse a cached) local vision analysis for one captured screenshot.
137 |  * Cache key is the full plan §8.1 composite: (imageHash, viewport, dpr,
138 |  * modelId, modelVersion, inferenceConfigHash) — so a viewport resize or a
139 |  * config change (e.g. INFERENCE_THRESHOLD) correctly misses instead of
140 |  * returning a stale result (plan §8.2 rules 3/4).
141 |  *
142 |  * Empty detections are a valid, expected outcome (flat/synthetic pages) and
143 |  * are returned as an empty array rather than treated as an error.
144 |  */
145 | export async function runVisionAnalysis(input: RunVisionAnalysisInput): Promise<RawVisionResult> {
146 |   const cacheParams = {
147 |     screenshotDataUrl: input.screenshotDataUrl,
148 |     viewportWidth: input.viewportWidth,
149 |     viewportHeight: input.viewportHeight,
150 |     devicePixelRatio: input.devicePixelRatio,
151 |     modelId: MODEL_ID,
152 |     modelVersion: MODEL_VERSION,
153 |     inferenceConfigHash: INFERENCE_CONFIG_HASH,
154 |   };
155 | 
156 |   const cached = lookupVisionCache(cacheStore, { ...cacheParams, requestId: input.requestId });
157 |   if (cached) return cached;
158 | 
159 |   const { detector, backend } = await ensureDetector();
160 |   const prepared = await prepareScreenshotForModel(input.screenshotDataUrl);
161 | 
162 |   const t0 = performance.now();
163 |   const raw = await detector(prepared.dataUrl, { threshold: INFERENCE_THRESHOLD });
164 |   const inferenceTimeMs = performance.now() - t0;
165 | 
166 |   const result: RawVisionResult = {
167 |     requestId: input.requestId,
168 |     modelId: MODEL_ID,
169 |     modelVersion: MODEL_VERSION,
170 |     backend,
171 |     imageWidth: prepared.modelSize.width,
172 |     imageHeight: prepared.modelSize.height,
173 |     detections: mapDetections(raw),
174 |     inferenceTimeMs,
175 |     cached: false,
176 |   };
177 | 
178 |   storeVisionCache(cacheStore, cacheParams, result);
179 |   return result;
180 | }
181 | 
182 | /** Test/debug hook: current cache size (used by verify.js Phase 4 checks). */
183 | export function getVisionCacheSize(): number {
184 |   return cacheStore.size;
185 | }

