166 | export function decideExclusion(el: DomElementLike): PrivacyDecision {
167 |   const ed = isEditable(el);
168 |   if (ed) return { suppressValue: true, suppressText: true, reason: "contenteditable" };
169 | 
170 |   const tag = (el.tagName || "").toUpperCase();
171 |   const type = (el.type ?? "").toLowerCase();
172 |   if (tag === "INPUT") {
173 |     if (type === "password") return { suppressValue: true, suppressText: false, reason: "password" };
174 |     if (type === "file") return { suppressValue: true, suppressText: false, reason: "file" };
175 |     if (type === "hidden") return { suppressValue: true, suppressText: false, reason: "hidden" };
176 |   }
177 |   return { suppressValue: false, suppressText: false, reason: null };
178 | }

