190 | /** Whether a form control's value may be captured (plan §4.2 B). */
191 | export function isValueCapturable(el: DomElementLike): boolean {
192 |   const tag = (el.tagName || "").toUpperCase();
193 |   if (tag !== "INPUT" && tag !== "TEXTAREA" && tag !== "SELECT") return false;
194 |   if (isEditable(el)) return false;
195 |   if (tag === "INPUT") {
196 |     const type = (el.type ?? "text").toLowerCase();
197 |     if (HARD_EXCLUDED_INPUT_TYPES.has(type)) return false;
198 |     return VALUE_TYPES.has(type);
199 |   }
200 |   return true; // TEXTAREA / SELECT
201 | }

