212 | export function captureStructuralText(el: DomElementLike): string | null {
213 |   // Only leaf nodes (no element children) yield structural text — we never
214 |   // stringify an ancestor's combined text (no document.body.innerText dumps).
215 |   if (el.children.length > 0) return null;
216 |   if (isEditable(el)) return null;
217 |   const raw = el.textContent;
218 |   if (raw == null) return null;
219 |   const s = String(raw).replace(/\s+/g, " ").trim();
220 |   return s.length === 0 ? null : truncateStructuralText(s);
221 | }

