chunk_a3410193bfdf8bc4.numbered_code:
257 | 
258 | interface WalkState {
259 |   max: number;
260 |   count: number;
261 |   truncated: boolean;
262 | }
263 | 
264 | export function serializeElement(
265 |   el: DomElementLike,
266 |   indexPath: readonly number[],
267 |   viewport: ViewportLike,
268 |   walker: WalkState
269 | ): CapturedElement | null {
270 |   if (walker.count >= walker.max) {
271 |     walker.truncated = true;
272 |     return null;
273 |   }
274 |   walker.count += 1;
275 | 
276 |   const tag = (el.tagName || "").toUpperCase();
277 |   const rect = rectOf(el);
278 |   const aria = {
279 |     label: attr(el, "aria-label"),
280 |     labelledby: attr(el, "aria-labelledby"),
281 |     describedby: attr(el, "aria-describedby"),
282 |     hidden: attr(el, "aria-hidden") === "true" ? true : null,
283 |     live: attr(el, "aria-live"),
284 |     expanded: attr(el, "aria-expanded") === "true" ? true : null,
285 |   };
286 | 
287 |   const node: CapturedElement = {
288 |     id: buildStableId(indexPath),
289 |     tag,
290 |     type: tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" ? (el.type ?? null) : null,
291 |     role: attr(el, "role"),
292 |     aria,
293 |     attrs: captureAttributes(el),
294 |     rect,
295 |     visible: isElementVisible(el, viewport),
296 |     disabled: !!el.disabled,
297 |     text: captureStructuralText(el),
298 |     value: captureUserValue(el),
299 |     children: [],
300 |   };
301 | 
302 |   for (let i = 0; i < el.children.length; i++) {
303 |     const child = el.children[i];
304 |     if (!child) continue;
305 |     // Dev 5 integration: the extension's own injected UI (status panel) is
306 |     // not page content — never walk it, never count it, never let it reach
307 |     // Dev 2/the sanitized payload/the LLM.
308 |     if (attr(child, PERCEIVE_UI_MARKER_ATTR) === "true") continue;
309 |     const c = serializeElement(child, [...indexPath, i], viewport, walker);
310 |     if (c) node.children.push(c);
311 |   }
312 |   return node;
313 | }

chunk_82366c407fcc643b.numbered_code:
314 | 
315 | export function buildDomSnapshot(
316 |   root: DomElementLike,
317 |   state: {
318 |     requestId: string;
319 |     domCapturedAt: number;
320 |     viewport: ViewportLike;
321 |     devicePixelRatio: number;
322 |     scroll: ScrollLike;
323 |   }
324 | ): DomSnapshot {
325 |   const walker: WalkState = { max: MAX_CAPTURE_ELEMENTS, count: 0, truncated: false };
326 |   // Root's indexPath MUST be [] (id ""), not [0] — `stampElementIds()`
327 |   // (dom-capture.ts) stamps the SAME real root as "" and its children as
328 |   // [i], not [0, i]. Root previously started at [0] here, giving every
329 |   // non-root element an id one path-segment longer than what was actually
330 |   // stamped onto the live DOM — e.g. the real login button was stamped
331 |   // "0.1.1.2" while this produced "0.0.1.1.2" for the same element. Every
332 |   // click/type action Dev 4 ever attempted against a non-root element was
333 |   // therefore looking up an id that could never exist in the DOM
334 |   // (`target_element_not_found`), independent of any timing/race — root-
335 |   // caused via direct reproduction (verify.js test33), not a race condition.
336 |   const rootNode = serializeElement(root, [], state.viewport, walker);
337 |   const elements = rootNode ? [rootNode] : [];
338 |   const count = countNodes(elements);
339 |   return {
340 |     requestId: state.requestId,
341 |     domCapturedAt: state.domCapturedAt,
342 |     viewport: state.viewport,
343 |     devicePixelRatio: state.devicePixelRatio,
344 |     scroll: state.scroll,
345 |     elements,
346 |     elementCount: count,
347 |     truncated: walker.truncated,
348 |   };
349 | }

chunk_ca50c36dcf973daa.numbered_code:
350 | 
351 | export function countNodes(nodes: readonly CapturedElement[]): number {
352 |   let n = 0;
353 |   for (const node of nodes) {
354 |     n += 1;
355 |     n += countNodes(node.children);
356 |   }
357 |   return n;
358 | }

