chunk_6e18ffeafb25ed11.numbered_code:
  1 | /**
  2 |  * Coordinate system utilities (Dev 1, Phase 2 §2.4).
  3 |  *
  4 |  * DOM element bounding boxes and vision (model) bounding boxes must be
  5 |  * expressible in one coordinate system. This module provides pure conversion
  6 |  * helpers between:
  7 |  *
  8 |  *   CSS pixels  (element.getBoundingClientRect)  — "design" coordinates
  9 |  *   screenshot  pixels (captureVisibleTab output) — css × devicePixelRatio
 10 |  *   model input pixels (post-downscale image fed to the ONNX model)
 11 |  *
 12 |  * All helpers are pure (no DOM/Chrome access) and fully unit-tested.
 13 |  */
 14 | 
 15 | export interface RectLike {
 16 |   x: number;
 17 |   y: number;
 18 |   width: number;
 19 |   height: number;
 20 | }
 21 | 
 22 | export interface SizeLike {
 23 |   width: number;
 24 |   height: number;
 25 | }
 26 | 
 27 | export interface PointLike {
 28 |   x: number;
 29 |   y: number;
 30 | }
 31 | 
 32 | /** A numerical box {x, y, width, height}. Also the vision output shape. */
 33 | export interface BoxLike {
 34 |   x: number;
 35 |   y: number;
 36 |   width: number;
 37 |   height: number;
 38 | }
 39 | 
 40 | /** CSS-pixel → screenshot-pixel conversion scale factor. */
 41 | export function cssToScreenshotScale(devicePixelRatio: number): number {
 42 |   if (!Number.isFinite(devicePixelRatio) || devicePixelRatio <= 0) {
 43 |     throw new Error(`invalid devicePixelRatio: ${devicePixelRatio}`);
 44 |   }
 45 |   return devicePixelRatio;
 46 | }
 47 | 
 48 | /** Convert a CSS-pixel point to screenshot-pixel coordinates. */
 49 | export function cssPointToScreenshotPoint(
 50 |   p: PointLike,
 51 |   devicePixelRatio: number
 52 | ): PointLike {
 53 |   return {
 54 |     x: p.x * cssToScreenshotScale(devicePixelRatio),
 55 |     y: p.y * cssToScreenshotScale(devicePixelRatio),
 56 |   };
 57 | }
 58 | 
 59 | /** Convert a CSS-pixel rect to screenshot-pixel rect. */
 60 | export function cssRectToScreenshotRect(
 61 |   r: RectLike,
 62 |   devicePixelRatio: number
 63 | ): RectLike {
 64 |   const s = cssToScreenshotScale(devicePixelRatio);
 65 |   return { x: r.x * s, y: r.y * s, width: r.width * s, height: r.height * s };
 66 | }
 67 | 
 68 | /** Inverse of {@link cssRectToScreenshotRect}. */
 69 | export function screenshotRectToCssRect(
 70 |   r: RectLike,
 71 |   devicePixelRatio: number
 72 | ): RectLike {
 73 |   const s = cssToScreenshotScale(devicePixelRatio);
 74 |   return { x: r.x / s, y: r.y / s, width: r.width / s, height: r.height / s };
 75 | }
 76 | 
 77 | /**
 78 |  * Map a box expressed in model-input pixels onto screenshot pixels. The model
 79 |  * image (<modelSize>) may be a downscaled canvas of the raw screenshot
 80 |  * (<screenshotSize>); each model box is scaled by (screenshot / model).
 81 |  */
 82 | export function modelBoxToScreenshotRect(
 83 |   box: BoxLike,
 84 |   modelSize: SizeLike,
 85 |   screenshotSize: SizeLike
 86 | ): BoxLike {
 87 |   if (modelSize.width <= 0 || modelSize.height <= 0) {
 88 |     throw new Error(`invalid model size: ${modelSize.width}x${modelSize.height}`);
 89 |   }
 90 |   if (screenshotSize.width <= 0 || screenshotSize.height <= 0) {
 91 |     throw new Error(`invalid screenshot size: ${screenshotSize.width}x${screenshotSize.height}`);
 92 |   }
 93 |   const sx = screenshotSize.width / modelSize.width;
 94 |   const sy = screenshotSize.height / modelSize.height;
 95 |   return {
 96 |     x: box.x * sx,
 97 |     y: box.y * sy,
 98 |     width: box.width * sx,
 99 |     height: box.height * sy,
100 |   };
101 | }
102 | 
103 | /** Model-input box → CSS-pixel box (model → screenshot → /dpr). */
104 | export function modelBoxToCssRect(
105 |   box: BoxLike,
106 |   modelSize: SizeLike,
107 |   screenshotSize: SizeLike,
108 |   devicePixelRatio: number
109 | ): BoxLike {
110 |   return screenshotRectToCssRect(
111 |     modelBoxToScreenshotRect(box, modelSize, screenshotSize),
112 |     devicePixelRatio
113 |   );
114 | }
115 | 
116 | /** Clamp a box so it lies entirely inside the given bounds. */
117 | export function clampBoxToBounds(box: BoxLike, bounds: SizeLike): BoxLike {
118 |   const x = Math.max(0, box.x);
119 |   const y = Math.max(0, box.y);
120 |   const width = Math.min(box.width, bounds.width - x);
121 |   const height = Math.min(box.height, bounds.height - y);
122 |   return { x, y, width: Math.max(0, width), height: Math.max(0, height) };
123 | }
124 | 
125 | /**
126 |  * Validate a numerical bounding box: finite non-negative coordinates, positive
127 |  * width/height, and (optionally) fully within the given image bounds.
128 |  */
129 | export function isValidBox(box: BoxLike, within?: SizeLike): boolean {
130 |   const finite =
131 |     [box.x, box.y, box.width, box.height].every((v) => Number.isFinite(v)) &&
132 |     box.width > 0 &&
133 |     box.height > 0;
134 |   if (!finite) return false;
135 |   if (!within) return true;
136 |   return box.x >= 0 && box.y >= 0 && box.x + box.width <= within.width && box.y + box.height <= within.height;
137 | }
138 | 
139 | /** Force a screen-relative css rect to be inside the viewport (negative-layout guards). */
140 | export function sanitizeCssRect(r: RectLike, viewport: SizeLike): RectLike {
141 |   return clampBoxToBounds({ ...r }, viewport);
142 | }
143 | 
144 | /**
145 |  * Compute the target size for a screenshot fed to the local vision model
146 |  * (Phase 4, plan `SCREENSHOT_MAX_LONG_EDGE`). Downscales so the longer edge
147 |  * is at most `maxLongEdge`, preserving aspect ratio; images already at or
148 |  * under the cap are returned unchanged (never upscaled). Pure integer math,
149 |  * no canvas/DOM access, so it is unit-testable independent of the offscreen
150 |  * document that actually draws the resized image.
151 |  */
152 | export function computeDownscaleSize(natural: SizeLike, maxLongEdge: number): SizeLike {
153 |   if (natural.width <= 0 || natural.height <= 0) {
154 |     throw new Error(`invalid natural size: ${natural.width}x${natural.height}`);
155 |   }
156 |   if (!Number.isFinite(maxLongEdge) || maxLongEdge <= 0) {
157 |     throw new Error(`invalid maxLongEdge: ${maxLongEdge}`);
158 |   }
159 |   const longEdge = Math.max(natural.width, natural.height);
160 |   if (longEdge <= maxLongEdge) {
161 |     return { width: Math.round(natural.width), height: Math.round(natural.height) };
162 |   }
163 |   const scale = maxLongEdge / longEdge;
164 |   return {
165 |     width: Math.max(1, Math.round(natural.width * scale)),
166 |     height: Math.max(1, Math.round(natural.height * scale)),
167 |   };
168 | }

chunk_6c704b4f6ec2cdba.numbered_code:
  1 | /**
  2 |  * Typed message contracts for Content Script ↔ Service Worker ↔ Offscreen
  3 |  * Document communication.
  4 |  *
  5 |  * All messages are discriminated unions on `type`. Structure is enforced by
  6 |  * runtime validators (used by every listener before dispatch) so a malformed
  7 |  * message can never reach a handler.
  8 |  *
  9 |  * Phase 1 implemented PING / OFFSCREEN_* / ERROR. Phase 2 implements capture
 10 |  * (DOM_CAPTURE_*, SCREENSHOT plumbing is internal to the SW), Phase 3 the
 11 |  * mutation channel (MUTATION_DETECTED), Phase 4 local vision
 12 |  * (ANALYSIS_*). Every cross-context exchange is correlated by `requestId`.
 13 |  */
 14 | 
 15 | import type { RequestMeta } from "./request-id";
 16 | import { isRequestMeta } from "./request-id";
 17 | import type { ContextType, MessageEnvelope } from "./types";
 18 | import type { DomSnapshot } from "./capture";
 19 | import type { RawVisionResult, CorrelatedCapture } from "./types";
 20 | 
 21 | export const MESSAGE_TYPES = {
 22 |   // Phase 1 – liveness / scaffold
 23 |   PING: "PING",
 24 |   PING_RESPONSE: "PING_RESPONSE",
 25 |   OFFSCREEN_READY: "OFFSCREEN_READY",
 26 |   OFFSCREEN_PING: "OFFSCREEN_PING",
 27 |   OFFSCREEN_PING_RESPONSE: "OFFSCREEN_PING_RESPONSE",
 28 |   ERROR_RESPONSE: "ERROR_RESPONSE",
 29 |   // Phase 2 – synchronized capture graph
 30 |   CAPTURE_REQUEST: "CAPTURE_REQUEST", // (any context) → SW: run one full capture+analysis
 31 |   DOM_CAPTURE_REQUEST: "DOM_CAPTURE_REQUEST", // SW → content: do the DOM walk
 32 |   DOM_CAPTURE_RESULT: "DOM_CAPTURE_RESULT", // content → SW: structural DOM snapshot
 33 |   SCREENSHOT_REQUEST: "SCREENSHOT_REQUEST", // declared (Phase 4 offscreen uses ANALYSIS_*)
 34 |   SCREENSHOT_RESULT: "SCREENSHOT_RESULT",
 35 |   CAPTURE_RESULT: "CAPTURE_RESULT", // SW → subscribers: the correlated capture package
 36 |   // Phase 3 – mutation / orchestration
 37 |   MUTATION_DETECTED: "MUTATION_DETECTED", // content → SW
 38 |   INVALIDATE_CACHE: "INVALIDATE_CACHE",
 39 |   // Phase 4 – local vision
 40 |   ANALYSIS_REQUEST: "ANALYSIS_REQUEST", // SW → offscreen
 41 |   ANALYSIS_RESULT: "ANALYSIS_RESULT", // offscreen → SW
 42 |   // Redaction (Dev 2 visual redaction, drawn in the offscreen doc's canvas)
 43 |   REDACT_REQUEST: "REDACT_REQUEST", // SW → offscreen
 44 |   REDACT_RESULT: "REDACT_RESULT", // offscreen → SW
 45 | } as const;
 46 | 
 47 | export type MessageType = (typeof MESSAGE_TYPES)[keyof typeof MESSAGE_TYPES];
 48 | 
 49 | /** Leaf union members. */
 50 | type PingRequest = RequestMeta & {
 51 |   type: typeof MESSAGE_TYPES.PING;
 52 |   origin: ContextType;
 53 | };
 54 | type PingResponse = RequestMeta & {
 55 |   type: typeof MESSAGE_TYPES.PING_RESPONSE;
 56 |   ok: true;
 57 |   origin: ContextType;
 58 |   swStartedAt: number;
 59 | };
 60 | 
 61 | type OffscreenReady = RequestMeta & {
 62 |   type: typeof MESSAGE_TYPES.OFFSCREEN_READY;
 63 |   ok: true;
 64 |   origin: ContextType;
 65 |   documentUrl: string;
 66 | };
 67 | 
 68 | type OffscreenPing = RequestMeta & {
 69 |   type: typeof MESSAGE_TYPES.OFFSCREEN_PING;
 70 |   origin: ContextType;
 71 | };
 72 | 
 73 | type OffscreenPingResponse = RequestMeta & {
 74 |   type: typeof MESSAGE_TYPES.OFFSCREEN_PING_RESPONSE;
 75 |   ok: boolean;
 76 |   origin: ContextType;
 77 |   documentUrl: string;
 78 |   readyAt: number;
 79 |   error?: string;
 80 | };
 81 | 
 82 | type ErrorResponse = RequestMeta & {
 83 |   type: typeof MESSAGE_TYPES.ERROR_RESPONSE;
 84 |   ok: false;
 85 |   origin: ContextType;
 86 |   error: string;
 87 | };
 88 | 
 89 | // ---- Phase 2 capture ----
 90 | 
 91 | export type CaptureSource = "initial" | "mutation" | "manual";
 92 | 
 93 | type CaptureRequest = RequestMeta & {
 94 |   type: typeof MESSAGE_TYPES.CAPTURE_REQUEST;
 95 |   origin: ContextType;
 96 |   source?: CaptureSource;
 97 |   tabId?: number;
 98 | };
 99 | 
100 | type DomCaptureRequest = RequestMeta & {
101 |   type: typeof MESSAGE_TYPES.DOM_CAPTURE_REQUEST;
102 |   origin: ContextType;
103 |   tabId?: number;
104 |   source?: CaptureSource;
105 | };
106 | 
107 | type DomCaptureResult = RequestMeta & {
108 |   type: typeof MESSAGE_TYPES.DOM_CAPTURE_RESULT;
109 |   ok: boolean;
110 |   origin: ContextType;
111 |   domSnapshot?: DomSnapshot;
112 |   error?: string;
113 | };
114 | 
115 | type CaptureResult = RequestMeta & {
116 |   type: typeof MESSAGE_TYPES.CAPTURE_RESULT;
117 |   ok: boolean;
118 |   origin: ContextType;
119 |   capture?: CorrelatedCapture;
120 |   /** Vision detections for this capture (plan §5.1 — the flow ends with the
121 |    * analysis result reaching the requester, not just the DOM+screenshot).
122 |    * Absent when Phase 4 analysis was skipped/failed independently of the
123 |    * capture itself; the capture can still be valid with no analysis. */
124 |   analysis?: RawVisionResult | null;
125 |   /** True when a newer capture superseded this request (plan §6). */
126 |   superseded?: boolean;
127 |   error?: string;
128 | };
129 | 
130 | // ---- Phase 4 vision ----
131 | 
132 | type AnalysisRequest = RequestMeta & {
133 |   type: typeof MESSAGE_TYPES.ANALYSIS_REQUEST;
134 |   origin: ContextType;
135 |   /** dataUrl of the captured screenshot (jpeg). */
136 |   screenshot: string;
137 |   /** Model-space/downscale info so the offscreen can map boxes back. */
138 |   screenshotContext?: {
139 |     viewportWidth: number;
140 |     viewportHeight: number;
141 |     devicePixelRatio: number;
142 |   };
143 | };
144 | 
145 | type AnalysisResult = RequestMeta & {
146 |   type: typeof MESSAGE_TYPES.ANALYSIS_RESULT;
147 |   ok: boolean;
148 |   origin: ContextType;
149 |   result?: RawVisionResult;
150 |   error?: string;
151 | };
152 | 
153 | // ---- Redaction ----
154 | 
155 | /** A DOM/Dev2-classified sensitive region in *screenshot*-pixel space (never
156 |  * a vision/YOLO detection box — see dev2-payload.ts's
157 |  * `buildScreenshotSensitiveRegions`, the only producer of this shape). */
158 | export interface RedactionRegion {
159 |   bounding_box: { x: number; y: number; w: number; h: number };
160 |   sensitivity_tier: 1 | 2 | 3;
161 | }
162 | 
163 | /** A screenshot-pixel point to sample before/after redaction, for real
164 |  * pixel-level verification that only sensitive regions changed. */
165 | export interface RedactionSamplePoint {
166 |   label: string;
167 |   isSensitive: boolean;
168 |   x: number;
169 |   y: number;
170 | }
171 | 
172 | export interface RedactionSampleResult {
173 |   label: string;
174 |   isSensitive: boolean;
175 |   before: [number, number, number, number];
176 |   after: [number, number, number, number];
177 |   changed: boolean;
178 |   isBlack: boolean;
179 | }
180 | 
181 | type RedactRequest = RequestMeta & {
182 |   type: typeof MESSAGE_TYPES.REDACT_REQUEST;
183 |   origin: ContextType;
184 |   screenshot: string;
185 |   sensitiveRegions: RedactionRegion[];
186 |   samplePoints?: RedactionSamplePoint[];
187 | };
188 | 
189 | type RedactResult = RequestMeta & {
190 |   type: typeof MESSAGE_TYPES.REDACT_RESULT;
191 |   ok: boolean;
192 |   origin: ContextType;
193 |   redactedDataUrl?: string;
194 |   samples?: RedactionSampleResult[];
195 |   error?: string;
196 | };
197 | 
198 | // ---- Phase 3 mutation ----
199 | 
200 | type MutationDetected = RequestMeta & {
201 |   type: typeof MESSAGE_TYPES.MUTATION_DETECTED;
202 |   origin: ContextType;
203 |   /** SW fills tab.id from the sender when the content script omits it. */
204 |   tabId?: number;
205 |   mutationCount: number;
206 |   source?: CaptureSource;
207 | };
208 | 
209 | type InvalidateCache = RequestMeta & {
210 |   type: typeof MESSAGE_TYPES.INVALIDATE_CACHE;
211 |   origin: ContextType;
212 | };
213 | 
214 | // ---- Public union ----
215 | 
216 | export type Message =
217 |   | PingRequest
218 |   | PingResponse
219 |   | OffscreenReady
220 |   | OffscreenPing
221 |   | OffscreenPingResponse
222 |   | ErrorResponse
223 |   | CaptureRequest
224 |   | DomCaptureRequest
225 |   | DomCaptureResult
226 |   | CaptureResult
227 |   | AnalysisRequest
228 |   | AnalysisResult
229 |   | RedactRequest
230 |   | RedactResult
231 |   | MutationDetected
232 |   | InvalidateCache;
233 | 
234 | export type RequestMessage = Extract<Message, { origin: ContextType }>;
235 | 
236 | const ORIGINS: readonly string[] = ["content-script", "background", "offscreen"];
237 |

