238 | export class MessageParseError extends Error {
239 |   constructor(message: string) {
240 |     super(message);
241 |     this.name = "MessageParseError";
242 |   }
243 | }

chunk_49e32c5736a91891.numbered_code:
244 | 
245 | /**
246 |  * Validate the raw value from `chrome.runtime.onMessage` and return a typed
247 |  * Message. Throws MessageParseError for anything structurally invalid so the
248 |  * caller can route to an ERROR_RESPONSE.
249 |  */
250 | export function parseMessage(value: unknown): Message {
251 |   const v = value as Record<string, unknown> | null;
252 |   if (!v || typeof v !== "object") {
253 |     throw new MessageParseError("Message must be an object");
254 |   }
255 |   const type = v.type;
256 |   if (typeof type !== "string" || !(type in MESSAGE_TYPES)) {
257 |     throw new MessageParseError(`Unknown message type: ${String(type)}`);
258 |   }
259 |   if (!isRequestMeta(value)) {
260 |     throw new MessageParseError("Message must carry a valid requestId and timestamp");
261 |   }
262 |   const origin = v.origin;
263 |   if (typeof origin !== "string" || !ORIGINS.includes(origin)) {
264 |     throw new MessageParseError(`Message must carry a valid origin, got: ${String(origin)}`);
265 |   }
266 |   return value as Message;
267 | }

chunk_974a597d2c425b8a.numbered_code:
268 | 
269 | /** Throws if the message is not the given type. Useful in handlers. */
270 | export function assertMessageType<T extends Message>(
271 |   message: Message,
272 |   expected: T["type"]
273 | ): asserts message is T {
274 |   if (message.type !== expected) {
275 |     throw new MessageParseError(`Expected type ${expected}, got ${message.type}`);
276 |   }
277 | }

chunk_f02e8c040c48d576.numbered_code:
278 | 
279 | /** Synthesize a typed ERROR_RESPONSE (used by listeners on parse/handle failure). */
280 | export function createErrorResponse(
281 |   input: unknown,
282 |   error: unknown,
283 |   origin: ContextType
284 | ): ErrorResponse {
285 |   const base = input as Partial<RequestMeta> | null;
286 |   const fallbackMeta = {
287 |     requestId: base && typeof base.requestId === "string" ? base.requestId : "unknown",
288 |     timestamp: Date.now(),
289 |   };
290 |   return {
291 |     ...fallbackMeta,
292 |     type: MESSAGE_TYPES.ERROR_RESPONSE,
293 |     ok: false,
294 |     origin,
295 |     error: String((error as Error)?.message ?? error),
296 |   };
297 | }
298 | 
299 | /** MessageEnvelope alias so consumers can use one term for both. */
300 | export type { MessageEnvelope };
301 | export { MESSAGE_TYPES as MessageTypes };
302 | export type { PingRequest, PingResponse };

chunk_1e8acccc835d14b9.numbered_code:
  1 | /**
  2 |  * Offscreen Document lifecycle management (idempotent, testable).
  3 |  *
  4 |  * The Service Worker calls `ensureOffscreenDocument()` before any inference
  5 |  * work. It is safe to call repeatedly: it inspects live extension contexts
  6 |  * (Chrome 116+) and only calls `chrome.offscreen.createDocument` when no
  7 |  * OFFSCREEN_DOCUMENT context exists, so service worker restarts never create
  8 |  * duplicates.
  9 |  *
 10 |  * Chrome APIs are injected via `deps` so the decision logic and the
 11 |  * create-document behavior are unit-testable without the browser.
 12 |  */
 13 | 
 14 | import {
 15 |   OFFSCREEN_JUSTIFICATION,
 16 |   OFFSCREEN_REASON,
 17 |   OFFSCREEN_URL,
 18 | } from "./constants";
 19 | 
 20 | export const OFFSCREEN_CONTEXT_TYPE = "OFFSCREEN_DOCUMENT";
 21 | 
 22 | export type ChromeOffscreenContextType =
 23 |   | "TAB"
 24 |   | "POPUP"
 25 |   | "BACKGROUND"
 26 |   | "OFFSCREEN_DOCUMENT"
 27 |   | "SIDE_PANEL"
 28 |   | "DEVELOPER_TOOLS";
 29 | 
 30 | export type OffscreenReason = typeof OFFSCREEN_REASON;
 31 | 
 32 | export interface OffscreenContextEntry {
 33 |   contextType: ChromeOffscreenContextType;
 34 |   documentUrl?: string;
 35 |   incognito?: boolean;
 36 | }
 37 | 
 38 | export interface OffscreenDocumentOutcome {
 39 |   /** True when this call created a new offscreen document. */
 40 |   created: boolean;
 41 |   /** True when an offscreen document exists after the call. */
 42 |   present: boolean;
 43 |   /** Known offscreen document URL(s), if reported by the runtime. */
 44 |   documentUrls: string[];
 45 | }
 46 | 
 47 | export interface OffscreenDeps {
 48 |   getContexts(filter: {
 49 |     contextTypes: ChromeOffscreenContextType[];
 50 |   }): Promise<OffscreenContextEntry[]>;
 51 |   createDocument(createProperties: {
 52 |     url: string;
 53 |     reasons: OffscreenReason[];
 54 |     justification: string;
 55 |   }): Promise<void>;
 56 |   getURL(path: string): string;
 57 | }
 58 | 
 59 | function defaultDeps(): OffscreenDeps {
 60 |   const chromeApi = (globalThis as { chrome?: typeof chrome }).chrome;
 61 |   if (!chromeApi || typeof chromeApi.runtime?.getContexts !== "function") {
 62 |     throw new Error("chrome.runtime.getContexts is unavailable (Chrome < 116)");
 63 |   }
 64 |   if (typeof chromeApi.offscreen?.createDocument !== "function") {
 65 |     throw new Error("chrome.offscreen.createDocument is unavailable");
 66 |   }
 67 |   return {
 68 |     getContexts: (filter) =>
 69 |       chromeApi.runtime
 70 |         .getContexts(filter as chrome.runtime.ContextFilter)
 71 |         .then((entries) =>
 72 |           entries.map((e) => ({
 73 |             contextType: e.contextType as ChromeOffscreenContextType,
 74 |             documentUrl: e.documentUrl,
 75 |             incognito: e.incognito,
 76 |           }))
 77 |         ),
 78 |     createDocument: (props) =>
 79 |       chromeApi.offscreen.createDocument(props as chrome.offscreen.CreateParameters),
 80 |     getURL: (path) => chromeApi.runtime.getURL(path),
 81 |   };
 82 | }
 83 | 
 84 | /** Pure decision: should we create a new offscreen document right now? */
 85 | export function shouldCreateOffscreenDocument(
 86 |   entries: readonly OffscreenContextEntry[]
 87 | ): boolean {
 88 |   return !entries.some((e) => e.contextType === OFFSCREEN_CONTEXT_TYPE);
 89 | }
 90 | 
 91 | /**
 92 |  * Ensure an offscreen document exists, creating one if and only if none does.
 93 |  * Idempotent across service worker restarts.
 94 |  */
 95 | export async function ensureOffscreenDocument(deps: OffscreenDeps = defaultDeps()): Promise<
 96 |   OffscreenDocumentOutcome
 97 | > {
 98 |   const filter = { contextTypes: [OFFSCREEN_CONTEXT_TYPE] as ChromeOffscreenContextType[] };
 99 |   const before = await deps.getContexts(filter);
100 |   const needed = shouldCreateOffscreenDocument(before);
101 | 
102 |   let created = false;
103 |   if (needed) {
104 |     await deps.createDocument({
105 |       url: deps.getURL(OFFSCREEN_URL),
106 |       reasons: [OFFSCREEN_REASON],
107 |       justification: OFFSCREEN_JUSTIFICATION,
108 |     });
109 |     created = true;
110 |   }
111 | 
112 |   // Re-read after (possibly) creating to report ground truth.
113 |   const after = await deps.getContexts(filter);
114 |   const present = shouldCreateOffscreenDocument(after) === false;
115 |   const documentUrls = after
116 |     .filter((e) => e.contextType === OFFSCREEN_CONTEXT_TYPE)
117 |     .map((e) => e.documentUrl ?? OFFSCREEN_URL);
118 | 
119 |   return { created, present, documentUrls };
120 | }

chunk_accc22c9d5461705.numbered_code:
 1 | /**
 2 |  * Shared request correlation infrastructure.
 3 |  *
 4 |  * Every cross-context request in Perceive carries a `requestId` and a
 5 |  * `timestamp` so messages can be correlated, de-duplicated, and ordered
 6 |  * (see LATEST_REQUEST_WINS policy planned for Phase 5).
 7 |  */
 8 | 
 9 | export interface RequestMeta {
10 |   /** Unique, unforgeable id for a single request/response exchange. */
11 |   requestId: string;
12 |   /** Wall-clock time (ms since epoch) at which the message was created. */
13 |   timestamp: number;
14 | }
15 | 
16 | /**
17 |  * Generate a globally unique request id. Prefers `crypto.randomUUID()`
18 |  * (available in MV3 service worker, offscreen document, and content script
19 |  * contexts) and falls back to a time+entropy hybrid elsewhere (e.g. jest).
20 |  */
21 | export function createRequestId(): string {
22 |   const cryptoObj = globalThis.crypto;
23 |   if (cryptoObj && typeof cryptoObj.randomUUID === "function") {
24 |     return cryptoObj.randomUUID();
25 |   }
26 |   return `req_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 12)}`;
27 | }
28 | 
29 | /** Build a fresh RequestMeta (id + timestamp) for a new message. */
30 | export function createRequestMeta(): RequestMeta {
31 |   return { requestId: createRequestId(), timestamp: Date.now() };
32 | }
33 | 
34 | /** Structural guard for RequestMeta-valued values. */
35 | export function isRequestMeta(value: unknown): value is RequestMeta {
36 |   const v = value as Record<string, unknown> | null;
37 |   return (
38 |     !!v &&
39 |     typeof v.requestId === "string" &&
40 |     v.requestId.length > 0 &&
41 |     typeof v.timestamp === "number" &&
42 |     Number.isFinite(v.timestamp)
43 |   );
44 | }

