  1 | /**
  2 |  * Shared type contracts for the Perceive extension.
  3 |  *
  4 |  * Phase 1 establishes only the correlation envelope and the context taxonomy.
  5 |  * Later phases extend these types (DOM snapshot, capture metadata, vision
  6 |  * results) without changing the message transport.
  7 |  */
  8 | 
  9 | /** Which extension context produced / consumed a message. */
 10 | export const CONTEXT = {
 11 |   CONTENT_SCRIPT: "content-script",
 12 |   BACKGROUND: "background",
 13 |   OFFSCREEN: "offscreen",
 14 | } as const;
 15 | 
 16 | export type ContextType = (typeof CONTEXT)[keyof typeof CONTEXT];
 17 | 
 18 | /** Message classification used for routing and validation. */
 19 | export const MESSAGE_KIND = {
 20 |   REQUEST: "request",
 21 |   RESPONSE: "response",
 22 |   EVENT: "event",
 23 | } as const;
 24 | 
 25 | export type MessageKind = (typeof MESSAGE_KIND)[keyof typeof MESSAGE_KIND];
 26 | 
 27 | /**
 28 |  * Correlation envelope carried by every message. The full capture-metadata
 29 |  * object (§5.2 of the plan: domCapturedAt, screenshotCapturedAt, ...) is a
 30 |  * Phase 2 concern and deliberately NOT declared here yet.
 31 |  */
 32 | export interface MessageEnvelope {
 33 |   requestId: string;
 34 |   timestamp: number;
 35 |   origin: ContextType;
 36 | }
 37 | 
 38 | export interface CaptureMetadata {
 39 |   requestId: string;
 40 |   domCapturedAt: number;
 41 |   screenshotCaptureStartedAt: number;
 42 |   screenshotCapturedAt: number;
 43 |   captureDelayMs: number;
 44 |   screenshotDurationMs: number;
 45 |   viewportWidth: number;
 46 |   viewportHeight: number;
 47 |   devicePixelRatio: number;
 48 |   scrollX: number;
 49 |   scrollY: number;
 50 | }
 51 | 
 52 | /**
 53 |  * A single correlated capture (Phase 2 §2.3): DOM snapshot + screenshot +
 54 |  * per-stage timing, all tied to one requestId.
 55 |  */
 56 | export interface CorrelatedCapture {
 57 |   requestId: string;
 58 |   /** Where the capture originated. */
 59 |   source: "initial" | "mutation" | "manual";
 60 |   tabId?: number;
 61 |   timing: CaptureMetadata;
 62 |   domCapturedAt: number;
 63 |   screenshotStartTime: number;
 64 |   screenshotEndTime: number;
 65 |   viewport: { width: number; height: number };
 66 |   devicePixelRatio: number;
 67 |   scroll: { x: number; y: number };
 68 |   /** DOM snapshot object (raw structural DomSnapshot). */
 69 |   dom: unknown;
 70 |   /** Screenshot as a local data URL (never exported). */
 71 |   screenshot: {
 72 |     dataUrl: string;
 73 |     format: string;
 74 |     quality: number;
 75 |   };
 76 |   /** Screenshot natural pixel size (filled in by the offscreen decode). */
 77 |   screenshotPixelSize?: { width: number; height: number };
 78 | }
 79 | 
 80 | /**
 81 |  * Phase 4 output contract (Dev 1 — raw vision result, NO sensitivity
 82 |  * classification; that is Dev 2's job).
 83 |  */
 84 | export interface VisionBoundingBox {
 85 |   x: number;
 86 |   y: number;
 87 |   width: number;
 88 |   height: number;
 89 | }
 90 | 
 91 | export interface VisionDetection {
 92 |   label: string;
 93 |   confidence: number;
 94 |   boundingBox: VisionBoundingBox;
 95 | }
 96 | 
 97 | export interface RawVisionResult {
 98 |   requestId: string;
 99 |   modelId: string;
100 |   modelVersion: string;
101 |   backend: "webgpu" | "wasm";
102 |   /** Dimensions of the image actually fed to the model (model-space). */
103 |   imageWidth: number;
104 |   imageHeight: number;
105 |   /** Raw object detections, coordinates in model-image pixels. */
106 |   detections: VisionDetection[];
107 |   inferenceTimeMs: number;
108 |   /** True when the result came from the on-device cache. */
109 |   cached: boolean;
110 | }

