  1 | /**
  2 |  * On-device local-vision inference cache (Phase 4, plan §8.1 composite key):
  3 |  *
  4 |  *   CacheKey = { imageHash, viewportWidth, viewportHeight, devicePixelRatio,
  5 |  *                modelId, modelVersion, inferenceConfigHash }
  6 |  *
  7 |  * `imageHash` is a content hash of the exact screenshot bytes fed to the
  8 |  * model; the rest pins the cache entry to the exact model + backend config
  9 |  * that produced it (plan §8.2 invalidation rule 3/4: viewport/dpr change or
 10 |  * model/config change must miss, not return a stale result). Two captures of
 11 |  * an unchanged viewport (e.g. a debounced mutation burst with no visible
 12 |  * change) reuse the same inference result instead of re-running the model.
 13 |  *
 14 |  * Pure and injectable (a plain Map by default) so it is unit-testable
 15 |  * without the offscreen document or any ONNX runtime.
 16 |  */
 17 | 
 18 | import type { RawVisionResult } from "./types";
 19 | 
 20 | export interface VisionCacheKeyInput {
 21 |   imageHash: string;
 22 |   viewportWidth: number;
 23 |   viewportHeight: number;
 24 |   devicePixelRatio: number;
 25 |   modelId: string;
 26 |   modelVersion: string;
 27 |   inferenceConfigHash: string;
 28 | }
 29 | 
 30 | /** Build the stable composite cache key (plan §8.1). */
 31 | export function buildVisionCacheKey(input: VisionCacheKeyInput): string {
 32 |   return [
 33 |     input.modelId,
 34 |     input.modelVersion,
 35 |     input.inferenceConfigHash,
 36 |     input.viewportWidth,
 37 |     input.viewportHeight,
 38 |     input.devicePixelRatio,
 39 |     input.imageHash,
 40 |   ].join(":");
 41 | }
 42 | 
 43 | /**
 44 |  * Deterministic, allocation-light string hash (djb2 variant) for the
 45 |  * screenshot dataUrl. Not cryptographic — collision resistance for a
 46 |  * single-user, single-device cache of a few dozen entries is more than
 47 |  * sufficient, and it needs no Web Crypto / Node crypto dependency so it runs
 48 |  * identically in the offscreen document and in jest.
 49 |  */
 50 | export function hashString(input: string): string {
 51 |   let h1 = 0xdeadbeef ^ input.length;
 52 |   let h2 = 0x41c6ce57 ^ input.length;
 53 |   for (let i = 0; i < input.length; i++) {
 54 |     const ch = input.charCodeAt(i);
 55 |     h1 = Math.imul(h1 ^ ch, 2654435761);
 56 |     h2 = Math.imul(h2 ^ ch, 1597334677);
 57 |   }
 58 |   h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
 59 |   h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
 60 |   // Two 32-bit halves concatenated as unsigned hex -> effectively a 64-bit hash.
 61 |   return (h1 >>> 0).toString(16).padStart(8, "0") + (h2 >>> 0).toString(16).padStart(8, "0");
 62 | }
 63 | 
 64 | export interface VisionCacheStore {
 65 |   get(key: string): RawVisionResult | undefined;
 66 |   set(key: string, value: RawVisionResult): void;
 67 |   has(key: string): boolean;
 68 |   delete(key: string): boolean;
 69 |   clear(): void;
 70 |   readonly size: number;
 71 | }
 72 | 
 73 | /** Simple bounded Map-backed store: evicts the oldest entry past `maxEntries`. */
 74 | export function createVisionCacheStore(maxEntries = 50): VisionCacheStore {
 75 |   const map = new Map<string, RawVisionResult>();
 76 |   return {
 77 |     get: (key) => map.get(key),
 78 |     has: (key) => map.has(key),
 79 |     delete: (key) => map.delete(key),
 80 |     clear: () => map.clear(),
 81 |     set: (key, value) => {
 82 |       // Refresh insertion order on overwrite so recently-reused entries
 83 |       // survive eviction longer (simple LRU-ish behavior via Map order).
 84 |       if (map.has(key)) map.delete(key);
 85 |       map.set(key, value);
 86 |       while (map.size > maxEntries) {
 87 |         const oldestKey = map.keys().next().value;
 88 |         if (oldestKey === undefined) break;
 89 |         map.delete(oldestKey);
 90 |       }
 91 |     },
 92 |     get size() {
 93 |       return map.size;
 94 |     },
 95 |   };
 96 | }
 97 | 
 98 | export interface VisionCacheLookupParams {
 99 |   screenshotDataUrl: string;
100 |   viewportWidth: number;
101 |   viewportHeight: number;
102 |   devicePixelRatio: number;
103 |   modelId: string;
104 |   modelVersion: string;
105 |   inferenceConfigHash: string;
106 |   requestId: string;
107 | }
108 | 
109 | function keyFromParams(params: Omit<VisionCacheLookupParams, "requestId">): string {
110 |   return buildVisionCacheKey({
111 |     imageHash: hashString(params.screenshotDataUrl),
112 |     viewportWidth: params.viewportWidth,
113 |     viewportHeight: params.viewportHeight,
114 |     devicePixelRatio: params.devicePixelRatio,
115 |     modelId: params.modelId,
116 |     modelVersion: params.modelVersion,
117 |     inferenceConfigHash: params.inferenceConfigHash,
118 |   });
119 | }
120 | 
121 | /**
122 |  * Look up a cached result for the full composite key (plan §8.1). Returns
123 |  * the cached `RawVisionResult` (with `cached: true` and the original
124 |  * `requestId` swapped for the current one) or null on a miss.
125 |  */
126 | export function lookupVisionCache(
127 |   store: VisionCacheStore,
128 |   params: VisionCacheLookupParams
129 | ): RawVisionResult | null {
130 |   const hit = store.get(keyFromParams(params));
131 |   if (!hit) return null;
132 |   return { ...hit, requestId: params.requestId, cached: true };
133 | }
134 | 
135 | /** Store a freshly computed result, keyed by the full composite key. */
136 | export function storeVisionCache(
137 |   store: VisionCacheStore,
138 |   params: Omit<VisionCacheLookupParams, "requestId">,
139 |   result: RawVisionResult
140 | ): void {
141 |   store.set(keyFromParams(params), { ...result, cached: false });
142 | }

