34 | function makeControllableDeps(): { deps: CaptureGraphDeps; ctl: Controllable } {
35 |   const domGates: {
36 |     id: string;
37 |     resolve: (v: { domSnapshot: DomSnapshot; domCapturedAt: number }) => void;
38 |   }[] = [];
39 |   const ctl: Controllable = {
40 |     domCalls: [],
41 |     screenshotCalls: [],
42 |     resolveDom(index, id, domCapturedAt) {
43 |       domGates[index]?.resolve({
44 |         domSnapshot: fakeDomSnapshot(id, domCapturedAt ?? 1),
45 |         domCapturedAt: domCapturedAt ?? 1,
46 |       });
47 |     },
48 |   };
49 |   const deps: CaptureGraphDeps = {
50 |     now: () => 100,
51 |     requestDomCapture: (tabId, requestId, source) => {
52 |       ctl.domCalls.push({ tabId, requestId, source });
53 |       return new Promise((resolve) => domGates.push({ id: requestId, resolve }));
54 |     },
55 |     captureScreenshot: async (tabId) => {
56 |       ctl.screenshotCalls.push(tabId);
57 |       return { dataUrl: "data:image/jpeg;base64,QUJD", startedAt: 20, endedAt: 25 };
58 |     },
59 |   };
60 |   return { deps, ctl };
61 | }

