  1 | /**
  2 |  * Phase 3 unit tests for content/mutation-watcher.ts — the 250 ms debounce
  3 |  * that collapses mutation bursts into one capture trigger.
  4 |  */
  5 | 
  6 | import { MutationWatcher, type Scheduler } from "../src/content/mutation-watcher";
  7 | import { MUTATION_DEBOUNCE_MS } from "../src/shared/constants";
  8 | 
  9 | class FakeScheduler implements Scheduler {
 10 |   fires: (() => void)[] = [];
 11 |   setCalls = 0;
 12 |   clearCalls = 0;
 13 | 
 14 |   setTimeout(cb: () => void) {
 15 |     this.fires.push(cb);
 16 |     this.setCalls += 1;
 17 |     return this.setCalls;
 18 |   }
 19 | 
 20 |   clearTimeout() {
 21 |     this.clearCalls += 1;
 22 |   }
 23 | 
 24 |   /** Fire the currently scheduled debounce callback (advance the window). */
 25 |   advance(): void {
 26 |     const cb = this.fires.shift();
 27 |     if (cb) cb();
 28 |   }
 29 | }
 30 | 
 31 | describe("MutationWatcher", () => {
 32 |   it("merges a burst of mutations into a single trigger with the total count", () => {
 33 |     const scheduler = new FakeScheduler();
 34 |     const fires: number[] = [];
 35 |     const watcher = new MutationWatcher({
 36 |       debounceMs: MUTATION_DEBOUNCE_MS,
 37 |       onDebounced: (count) => fires.push(count),
 38 |       scheduler,
 39 |     });
 40 | 
 41 |     watcher.recordMutations(3);
 42 |     watcher.recordMutations(2);
 43 |     watcher.recordMutations(4);
 44 |     expect(scheduler.setCalls).toBe(1); // one timer for the whole burst
 45 |     expect(fires).toEqual([]);
 46 | 
 47 |     scheduler.advance();
 48 |     expect(fires).toEqual([9]);
 49 |   });
 50 | 
 51 |   it("starts a fresh window after a fire", () => {
 52 |     const scheduler = new FakeScheduler();
 53 |     const fires: number[] = [];
 54 |     const watcher = new MutationWatcher({
 55 |       debounceMs: MUTATION_DEBOUNCE_MS,
 56 |       onDebounced: (count) => fires.push(count),
 57 |       scheduler,
 58 |     });
 59 | 
 60 |     watcher.recordMutations(1);
 61 |     scheduler.advance();
 62 |     watcher.recordMutations(5);
 63 |     scheduler.advance();
 64 |     expect(fires).toEqual([1, 5]);
 65 |     expect(scheduler.setCalls).toBe(2);
 66 |   });
 67 | 
 68 |   it("flush() emits pending counts immediately", () => {
 69 |     const scheduler = new FakeScheduler();
 70 |     let fired = 0;
 71 |     const watcher = new MutationWatcher({
 72 |       debounceMs: MUTATION_DEBOUNCE_MS,
 73 |       onDebounced: (c) => {
 74 |         fired = c;
 75 |       },
 76 |       scheduler,
 77 |     });
 78 |     watcher.recordMutations(7);
 79 |     watcher.flush();
 80 |     expect(fired).toBe(7);
 81 |     expect(scheduler.clearCalls).toBe(1);
 82 |   });
 83 | 
 84 |   it("disconnect() cancels the timer and drops pending counts", () => {
 85 |     const scheduler = new FakeScheduler();
 86 |     let fired = 0;
 87 |     const watcher = new MutationWatcher({
 88 |       debounceMs: MUTATION_DEBOUNCE_MS,
 89 |       onDebounced: () => {
 90 |         fired += 1;
 91 |       },
 92 |       scheduler,
 93 |     });
 94 |     watcher.recordMutations(2);
 95 |     watcher.disconnect();
 96 |     scheduler.advance(); // stale callback must not fire after disconnect
 97 |     expect(fired).toBe(0);
 98 |     expect(scheduler.clearCalls).toBe(1);
 99 |   });
100 | 
101 |   it("ignores zero/negative counts", () => {
102 |     const scheduler = new FakeScheduler();
103 |     let fired = 0;
104 |     const watcher = new MutationWatcher({
105 |       debounceMs: MUTATION_DEBOUNCE_MS,
106 |       onDebounced: () => {
107 |         fired += 1;
108 |       },
109 |       scheduler,
110 |     });
111 |     watcher.recordMutations(0);
112 |     watcher.recordMutations(-1);
113 |     expect(scheduler.setCalls).toBe(0);
114 |     expect(fired).toBe(0);
115 |   });
116 | });

