39 | async function waitForTargetByUrl(filter, timeoutMs = 45000) {
40 |   const start = Date.now();
41 |   while (Date.now() - start < timeoutMs) {
42 |     try {
43 |       const list = await CDP.List({ port: PORT });
44 |       const match = list.find(filter);
45 |       if (match) return match;
46 |     } catch (_) {}
47 |     await sleep(400);
48 |   }
49 |   throw new Error("timeout waiting for target");
50 | }

