51 | 
52 | async function evalIn(wsUrl, expression) {
53 |   let client;
54 |   try {
55 |     client = await CDP({ target: wsUrl });
56 |     await client.Runtime.enable();
57 |     const res = await client.Runtime.evaluate({ expression, awaitPromise: true, returnByValue: true, timeout: 30000 });
58 |     if (res.exceptionDetails) {
59 |       return { __evalError: true, error: res.exceptionDetails.exception?.description || res.exceptionDetails.text };
60 |     }
61 |     return res.result.value;
62 |   } finally {
63 |     if (client) await client.close();
64 |   }
65 | }

