71 | async function evalInContentWorld(pageWs, expression) {
72 |   let client;
73 |   try {
74 |     client = await CDP({ target: pageWs });
75 |     const contexts = [];
76 |     client.Runtime.on("executionContextCreated", (p) => contexts.push(p.context));
77 |     await client.Runtime.enable();
78 |     const start = Date.now();
79 |     let contextId = null;
80 |     while (!contextId && Date.now() - start < 15000) {
81 |       contextId = findIsolatedWorldId(contexts) ?? null;
82 |       if (!contextId) await sleep(100);
83 |     }
84 |     if (!contextId) throw new Error("content-script isolated world not found");
85 |     const res = await client.Runtime.evaluate({ expression, contextId, awaitPromise: true, returnByValue: true, timeout: 30000 });
86 |     if (res.exceptionDetails) {
87 |       return { __evalError: true, error: res.exceptionDetails.exception?.description || res.exceptionDetails.text };
88 |     }
89 |     return res.result.value;
90 |   } finally {
91 |     if (client) await client.close();
92 |   }
93 | }

