 95 | async function waitForOrchestratorIdle(swWs, maxTicks = 100, tickMs = 300) {
 96 |   let status = null;
 97 |   let consecutiveIdle = 0;
 98 |   for (let i = 0; i < maxTicks; i++) {
 99 |     status = await evalIn(swWs, `__perceiveTest.getStatus()`);
100 |     const idle = !status?.orchestrator?.inflightRequestId && !status?.orchestrator?.pendingRequestId;
101 |     consecutiveIdle = idle ? consecutiveIdle + 1 : 0;
102 |     if (consecutiveIdle >= 2) break;
103 |     await sleep(tickMs);
104 |   }
105 |   return status;
106 | }

